-- 0281 lujo_pdf (inventario_lujo_pdf) — borra placeholder + entidades + puntuaciones reales
DELETE FROM puntuaciones WHERE categoria='lujo';
DELETE FROM entidades WHERE fuente='inventario_lujo_pdf';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','lujo','Turismo de lujo','La capital del bienestar preventivo y la longevidad en el Mediterráneo. Su infraestructura médica premium destaca por albergar la prestigiosa clínica internacional Buchinger Wilhelmi Marbella, un templo de ayuno terapéutico e integración médica donde magnates, aristócratas y celebridades mundiales realizan retiros de salud blindados bajo estricta confidencialidad. Cuenta con el centro de bienestar avanzado de Puente Romano Beach Resort (asociado a firmas cosméticas globales) y hospitales privados equipados con unidades VIP y helipuertos operativos. Todo este ecosistema de salud se complementa con urbanizaciones fortificadas de máxima seguridad, suites de 5 estrellas Gran Lujo, servicios de conserjería médica personalizada y alta cocina nutricional km 0.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','lujo','Turismo de lujo','El municipio residencial con mayor densidad de campos de golf de súper-lujo por habitante de España. Su infraestructura deportiva premium destaca por albergar el Valle del Golf y clubes hiper-exclusivos de admisión restringida como el Marbella Club Golf Resort (diseñado por Dave Thomas) [Image 1.4.1], Los Arqueros (diseñado por Severiano Ballesteros) y La Zagaleta Country Club (un coto residencial privado con dos campos de golf de uso estrictamente reservado para sus millonarios residentes). Este municipio alberga el resort de 5 estrellas Gran Lujo Anantara Villa Padierna Palace, dotado de tres campos de golf propios, club de tenis de alto rendimiento y helipuertos privados. [1, 2, 3].','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','lujo','Turismo de lujo','Destino de baja densidad residencial enfocado al turismo premium sibarita y deportivo. Su pilar fundamental es el resort Finca Cortesín, galardonado globalmente por su hotel de 5 estrellas Gran Lujo, su exclusivo club de playa y un campo de golf de nivel campeonato que ha albergado la Solheim Cup. El municipio ofrece un entorno de máxima discreción con promociones de villas de diseño.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','lujo','Turismo de lujo','La indiscutible capital del polo y el golf premium en Europa [Image 1.3.2]. Su infraestructura ecuestre cuenta con el Santa María Polo Club y el Ayala Polo Club, sedes del prestigioso Torneo Internacional de Polo que reúne a las mayores fortunas mundiales y familias reales. En el plano del golf, alberga el legendario Real Club Valderrama (considerado el mejor campo de la Europa continental, sede de la Ryder Cup) [Image 1.3.1], el Real Club de Golf Sotogrande y el exclusivo La Reserva Club. Todo este ecosistema deportivo se apoya en urbanizaciones privadas blindadas jalonadas por canales náuticos navegables, el hotel de 5 estrellas SO/ Sotogrande Spa & Golf Resort y helipuertos civiles autorizados.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90653','lujo','Turismo de lujo','Capital del "high-end lifestyle" estival europeo. Su infraestructura se apoya en Marina Ibiza y Marina Botafoch, preparadas para el atraque de megayates y rodeadas de terrazas de alta cocina y tiendas de firmas internacionales. Dispone de hoteles de 5 estrellas Gran Lujo como El Hotel Pacha y The Standard. Su oferta de ocio.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90023','lujo','Turismo de lujo','Municipio ibicenco que concentra la mayor cantidad de playas vírgenes combinadas con infraestructura de lujo dispersa. Alberga urbanizaciones exclusivas de alta seguridad como Vista Alegre. Es sede de los clubes de playa más cotizados del Mediterráneo (Blue Marlin en Cala Jondal, Cotton Beach Club) y restaurantes de alta cocina internacional. Su oferta hotelera premium incluye resorts de 5 estrellas como el 7Pines Resort Ibiza. Destaca por su alta densidad de villas de alquiler vacacional exclusivo orientadas a celebridades, con helipuertos privados y servicios de chef privado.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90851','lujo','Turismo de lujo','Alternativa de lujo relajado y discreto ("barefoot luxury"). Cuenta con su propio puerto deportivo premium y hoteles de 5 estrellas Gran Lujo orientados al bienestar físico y mental, como el Aguas de Ibiza Grand Luxe y el ME Ibiza. Reúne una excelente oferta gastronómica costera, clubes de playa exclusivos como Nikki Beach Ibiza y la urbanización privada de alto standing Roca Llisa, la cual alberga el único campo de golf de la isla.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','lujo','Turismo de lujo','Gran capital turística premium con actividad durante todo el año. Su fachada marítima alberga el Real Club Náutico de Palma y marinas preparadas para grandes esloras. El casco antiguo concentra la mayor densidad de hoteles boutique de 5 estrellas y Gran Lujo en palacios históricos reformados. Cuenta con un eje de "shopping" premium en el Paseo del Borne (Louis Vuitton, Gucci). Su oferta gastronómica incluye múltiples estrellas Michelin y clubes de playa exclusivos en su bahía, respaldados por campos de golf de primer nivel como Son Vida.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','lujo','Turismo de lujo','Nodo estratégico de la salud premium y la revitalización física en el archipiélago balear. Su infraestructura médica y de bienestar destaca por el espectacular Arabella Spa integrado en el hotel de 5 estrellas Gran Lujo St. Regis Mardavall Mallorca Resort, catalogado de forma recurrente como uno de los centros de talasoterapia y medicina tradicional china más avanzados y exclusivos de Europa continental. El municipio alberga prestigiosas clínicas privadas especializadas en medicina regenerativa, tratamientos de detoxificación celular y cirugía estética personalizada, respaldadas por un urbanismo blindado de baja densidad con mansiones de diseño de vanguardia y servicios de mayordomía privada las 24 horas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90017','lujo','Turismo de lujo','Refugio residencial de la élite internacional en el extremo occidental de la isla. Su núcleo marítimo, Port d''Andratx, combina la esencia marinera con amarres privados para yates deportivos y villas de diseño vanguardista colgadas sobre acantilados en urbanizaciones de alta seguridad como Monport. Cuenta con el campo Golf de Andratx y una selecta línea de restaurantes de alta cocina frente al mar, complementada por servicios de conserjería náutica personalizada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90020','lujo','Turismo de lujo','El máximo exponente del lujo bohemio e intelectual aislado en la Sierra de Tramuntana. Carece de puertos o campos de golf por su geografía, pero su puntuación se debe a su exclusividad residencial e inmobiliaria y a la presencia del hotel Belmond La Residencia, un establecimiento de 5 estrellas Gran Lujo que ofrece máxima privacidad a celebridades mundiales. Su oferta se complementa con restaurantes de alta cocina y calas vírgenes de acceso discreto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','lujo','Turismo de lujo','Sede de los búnkeres sociales y deportivos con los derechos de admisión más restrictivos de España. Su infraestructura premium destaca por el Real Club de la Puerta de Hierro, un club de campo hiper-exclusivo donde la membresía no se compra, sino que se hereda por estirpe familiar y exige la validación de comités aristocráticos. Cuenta con dos campos de golf de 18 hoyos de nivel campeonato, pistas de tenis de tierra batida, instalaciones hípicas de alta escuela y salones privados de alta seguridad. En su linde se despliegan urbanizaciones blindadas como Somontes y la Milla de Oro del shopping en el Barrio de Salamanca, dotada de servicios de "personal shopping" internacional en salas VIP privadas para grandes fortunas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28115','lujo','Turismo de lujo','El bastión de la élite empresarial, financiera y deportiva de la capital. Su infraestructura deportiva premium orbita alrededor del Club de Golf La Finca [Image 1.6.1], un espectacular campo urbano de última generación integrado en el búnker residencial hipervigilado de la urbanización La Finca. En su linde se sitúa el prestigioso complejo comercial y gastronómico LaFinca Grand Café y el club deportivo premium Reebok Sports Club. El entorno residencial destaca por mansiones inteligentes fortificadas con helipuertos privados y patrullas de seguridad perimetral militarizada que garantizan una total privacidad a los deportistas de élite y altos directivos multinacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','lujo','Turismo de lujo','Metrópolis global que combina turismo urbano, de negocios y de costa premium. Marina Port Vell ofrece amarres específicos para súper-yates en el centro de la ciudad. Su eje de compras de lujo se despliega en el Paseo de Gracia (Hermès, Prada, Cartier). Cuenta con una planta hotelera de 5 estrellas Gran Lujo icónica (Hotel Arts, W Barcelona, Majestic, Mandarin Oriental). Es un referente en alta cocina con un sólido listado de restaurantes Michelin y dispone de servicios de conserjería internacional, terminales de aviación privada y casinos de primer nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','lujo','Turismo de lujo','Destino costero de marcado carácter premium y cosmopolita. Cuenta con el Puerto de Aiguadolç, que ofrece amarres para yates deportivos y restauración de alta gama frente al mar. Su planta hotelera incluye establecimientos de 5 estrellas como el ME Sitges Terramar. El municipio destaca por sus mansiones de estilo indiano en el paseo marítimo, urbanizaciones exclusivas en las colinas (Levantina) y servicios de eventos corporativos y festivales VIP de repercusión internacional.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90035','lujo','Turismo de lujo','Centro neurálgico del shopping de marcas premium en la Costa Brava. Su puerto deportivo, Port d''Aro, ofrece excelentes instalaciones de amarre privados. Cuenta con urbanizaciones residenciales de alta seguridad en los acantilados circundantes (S''Agaró Vell), donde se encuentra el histórico y exclusivo Hostal de La Gavina, hotel de 5 estrellas Gran Lujo que ha hospedado a la aristocracia europea. Su oferta se complementa con una gastronomía mediterránea gourmet refinada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','lujo','Turismo de lujo','Considerado el municipio con la mayor concentración de hoteles de 5 estrellas Gran Lujo por metro cuadrado de Europa. Su infraestructura premium se agrupa en la zona de Costa Adeje, destacando el hotel Bahia del Duque, Royal Hideaway Corales Resort y el ultralujoso Las Villas. Cuenta con Puerto Colón para el chárter de yates privados y el campo de golf de campeonato Golf Costa Adeje (diseñado por Pepe Gancedo). Su oferta de ocio VIP incluye el exclusivo centro comercial Plaza del Duque (marcas internacionales), clubes de playa de alta gama como Le Club y helipuertos privados para transfers directos desde los aeropuertos de la isla.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38019','lujo','Turismo de lujo','El oasis definitivo del golf internacional y el aislamiento premium en las Islas Canarias. Su infraestructura deportiva está capitaneada por el espectacular campo Abama Golf, diseñado por la leyenda mundial Dave Thomas [Image 1.3.1]. Este trazado de campeonato cuenta con impresionantes vistas al océano Atlántico, cascadas naturales, búnkeres de arena blanca y miles de palmeras que crean un ecosistema único. Se integra directamente en el megacomplejo de súper-lujo Abama Resort, que alberga hoteles de 5 estrellas Gran Lujo, una academia de tenis de alta competición con pistas profesionales y espectaculares villas inteligentes fortificadas con total privacidad y helipuertos operativos para transfers directos desde los aeropuertos insulares.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38013','lujo','Turismo de lujo','Destino premium enfocado al sector náutico de gran eslora y al residencial de lujo geográfico. El Puerto de Los Gigantes sirve como base para yates de lujo que buscan privacidad junto a los acantilados. En sus escarpadas laderas se erigen complejos de villas modernas con piscinas infinitas de uso exclusivo para el turismo residencial centroeuropeo de alto poder adquisitivo, complementado con restaurantes boutique de alta cocina canaria de vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','lujo','Turismo de lujo','Epicentro del estilo de vida premium en Gran Canaria, concentrado en el área de Meloneras. Dispone de una planta hotelera de 5 estrellas de primer nivel, destacando el Lopesan Baobab Resort y el Seaside Grand Hotel Residencia (miembro de Leading Hotels of the World). Cuenta con los campos de golf exclusivos Maspalomas Golf y Meloneras Golf. Su infraestructura recreativa incluye el Casino de Gran Canaria, un paseo marítimo jalonado por boutiques de moda de alta gama y restaurantes gourmet especializados en producto atlántico, además de servicios consolidados de conserjería para yates en el cercano Pasito Blanco.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','lujo','Turismo de lujo','Conocido por el turismo náutico de alto standing gracias a la Marina de Puerto de Mogán y el Puerto Deportivo de Puerto Rico, puntos de atraque idóneos para embarcaciones recreativas de gran eslora. El municipio esconde resorts de 5 estrellas orientados al bienestar premium y urbanizaciones exclusivas en los barrancos de la zona (como el área de Anfi del Mar), que ofrecen playas privadas de arena blanca caribeña, clubes de playa con camas balinesas y servicios de helicóptero privado bajo demanda.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','lujo','Turismo de lujo','El refugio residencial más exclusivo de la Costa Blanca. Alberga la urbanización ultra-privada Altea Hills, un búnker de alta seguridad donde las fortunas internacionales poseen villas de diseño vanguardista. Su infraestructura náutica de primer nivel destaca por el Puerto Deportivo Marina Greenwich (Luis Campomanes), el único puerto del mundo situado exactamente sobre el Meridiano de Greenwich, dotado de amarres para yates de gran calado, restaurantes de alta cocina y clubes de estilo de vida premium. Cuenta también con el club de campo Altea Club de Golf.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','lujo','Turismo de lujo','Destino predilecto de la élite madrileña y europea que busca un "lujo discreto" integrado en la naturaleza. Su infraestructura se compone de calas de acceso restringido o marítimo y el Club Náutico de Jávea, especializado en yates deportivos de media y gran eslora. El mercado inmobiliario premium domina el municipio con mansiones multimillonarias situadas en los acantilados del Cabo de la Nao y la urbanización El Tosalet. La oferta gastronómica es de altísimo nivel, liderada por restaurantes con Estrellas Michelin como BonAmb.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03014','lujo','Turismo de lujo','Nota de ampliación estructural: Alejado del bullicio marítimo de su puerto central, el área de La Sella y Jesús Pobre constituye el búnker de exclusividad residencial y deportiva del municipio. Su infraestructura premium orbita alrededor de La Sella Golf, un prestigioso campo de campeonato de 27 hoyos diseñado por José María Olazábal, integrado en el exclusivo resort de 5 estrellas Denia Marriott La Sella Golf Resort & Spa. La zona cuenta con urbanizaciones blindadas con control de accesos perimetral avanzado y patrullas de seguridad permanente 24/7, donde fortunas europeas poseen exclusivas villas inteligentes de diseño contemporáneo y vistas despejadas al parque natural del Montgó.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','lujo','Turismo de lujo','El bastión residencial de la alta burguesía y las grandes fortunas industriales vascas. Su fisonomía destaca por los palacetes de la zona de Neguri y las mansiones del Paseo de Zugazarte. Dispone de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','lujo','Turismo de lujo','Municipio que esconde un reducto de alto standing inmobiliario y de estilo de vida premium en laCornisa Cantábrica, especialmente en los núcleos de Somo y Loredo. Es un destino predilecto para el turismo residencial de élite que busca surf de alta gama, hípica y golf. Cuenta con el Real Golf de Pedreña en sus inmediaciones inmediatas (el club histórico de Severiano Ballesteros). Alberga villas señoriales blindadas con acceso privado a acantilados, escuelas de surf premium personalizadas y restaurantes de alta cocina cántabra con Estrellas Michelin en el entorno rural.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','lujo','Turismo de lujo','Destino asturiano del "lujo indiano" y el turismo activo premium. Su principal infraestructura de exclusividad radica en el Paseo de la Playa de Santa Marina, flanqueado por joyas arquitectónicas de principios del siglo XX transformadas en palacetes residenciales privados y hoteles boutique de 5 estrellas. Su puerto deportivo da cabida a veleros de recreo de alta gama. La gastronomía local está altamente posicionada con restaurantes distinguidos y establecimientos con Estrella Michelin (como Ayalga), atrayendo a un perfil de visitante internacional sibarita.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','lujo','Turismo de lujo','Conocida como la capital del turismo de lujo en Galicia y el "Marbella del Norte". Su joya de infraestructura es el Puerto Deportivo Juan Carlos I, uno de los clubes náuticos más importantes del Atlántico, sede de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','lujo','Turismo de lujo','Epicentro del lujo aristocrático, el patrimonio histórico y el estilo de vida premium del sur de España. Su planta hotelera cuenta con leyendas de 5 estrellas Gran Lujo como el Hotel Alfonso XIII (un palacio de propiedad histórica) y el vanguardista CoolRooms Palacio de Villapanés. El "shopping" de alta costura e internacional se concentra en las calles Tetuán, Sierpes y la Plaza de la Magdalena. Dispone del Puerto de Sevilla, que permite la escala de yates y cruceros boutique premium directamente en el río Guadalquivir. Cuenta con terminal de aviación privada en el aeropuerto de San Pablo, el exclusivo Real Club Pineda (hípica y golf privado de admisión muy restringida) y una gastronomía de alta gama que fusiona el recetario andaluz tradicional con la vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','lujo','Turismo de lujo','Destino de turismo cultural y residencial de alta gama enfocado en la discreción. Alberga el hotel de 5 estrellas Gran Lujo Hospes Palacio del Bailío, una antigua casa palaciega con restos romanos bajo su suelo. Su infraestructura premium incluye el Real Club de Campo de Córdoba (campo de golf en plena Sierra Morena) y zonas residenciales exclusivas como El Brillante, donde se ubican mansiones históricas de grandes terratenientes. Su gastronomía de ultra-lujo está liderada por restaurantes con dos Estrellas Michelin como Noor, del chef Paco Morales, especializado en arqueología gastronómica andalusí.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','lujo','Turismo de lujo','El máximo exponente del "lujo descalzo" y el aislamiento exclusivo dentro del Parque Natural de Cabo de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47157','lujo','Turismo de lujo','Municipio que esconde una de las joyas más exclusivas del turismo premium mundial en la Ribera del Duero. Alberga el hotel Abadía Retuerta LeDomaine, un monasterio del siglo XII reconvertido en hotel de 5 estrellas Gran Lujo que ofrece un servicio de mayordomía personalizado de nivel internacional, helipuerto privado, una bodega de alta gama y el restaurante Refectorio (con Estrella Michelin y Estrella Verde). Las experiencias de este municipio se diseñan a medida para perfiles de alto poder adquisitivo (vuelos en globo privados, catas de barricas históricas).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','lujo','Turismo de lujo','La capital del turismo del vino de alta gama en la provincia burgalesa. Dispone de una infraestructura orientada al enoturismo de élite, con bodegas subterráneas históricas y complejos modernos que ofrecen visitas y catas privadas exclusivas para coleccionistas de vino mundiales. Cuenta con hoteles boutique premium integrados en viñedos y una gastronomía centrada en el asado tradicional castellano elevado a la alta cocina, atrayendo a empresarios y directivos de todo el país.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10086','lujo','Turismo de lujo','Histórico real sitio y destino de la aristocracia madrileña y europea. Su fisonomía está marcada por el Palacio Real de La Granja y sus monumentales jardines. Cuenta con hoteles boutique de alta gama y villas señoriales de gran valor histórico en zonas residenciales protegidas. Su oferta premium incluye el Club de Campo y de Golf La Faisanera (diseñado por José María Olazábal) y una gastronomía castellana gourmet de primer orden, todo en un entorno de máxima seguridad y tranquilidad a los pies de la Sierra de Guadarrama.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','lujo','Turismo de lujo','Municipio que alberga el núcleo de Formigal, el destino de turismo de esquí e invierno más exclusivo del Pirineo Aragonés. Su infraestructura premium destaca por pistas con zonas VIP exclusivas, remontes rápidos, servicios de guías de esquí personalizados y zonas de restauración "après-ski" de alto standing (como Marchica VIP). La planta hotelera cuenta con chalets de alta montaña de alquiler exclusivo y hoteles de 4 y 5 estrellas enfocados al bienestar de lujo y tratamientos de spa de montaña de alta gama.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','lujo','Turismo de lujo','Destino de turismo alpino y de naturaleza premium enfocado en la discreción. Ofrece refugios y chalets de piedra y madera de ultra-lujo aislados en el entorno del Parque Natural Posets-Maladeta. Cuenta con empresas de heliesquí privadas y guías de alta montaña para perfiles de alto poder adquisitivo, además de una selecta gastronomía pirenaica de vanguardia que atrae a la élite empresarial que busca desconexión absoluta.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','lujo','Turismo de lujo','Destino premium internacional que combina paisajes volcánicos con la sofisticación del "barefoot luxury". Su joya de infraestructura es Puerto Calero, una marina de gran calado sumamente exclusiva y protegida, diseñada para megayates, flanqueada por un paseo marítimo con boutiques de marcas internacionales y restaurantes gourmet. El municipio alberga urbanizaciones residenciales privadas de alta gama y hoteles de 5 estrellas de estética integrada en el entorno, como el Secrets Lanzarote Resort & Spa.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46070','lujo','Turismo de lujo','El principal bastión residencial y deportivo premium de la periferia de Valencia Capital. Su infraestructura de lujo gira en torno a la urbanización privada Torre en Conill, un complejo blindado con sistemas de seguridad avanzados donde residen empresarios y deportistas de élite. En su corazón se encuentra el Club de Golf Escorpión, uno de los clubes de campo privados más prestigiosos y tradicionales de la región, que exige estrictos requisitos de acceso.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13072','lujo','Turismo de lujo','Uno de los secretos mejor guardados del turismo de ultra-lujo y la discreción absoluta en.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','lujo','Turismo de lujo','Destino de turismo histórico, cultural y patrimonial con una sólida infraestructura premium dirigida a visitantes internacionales de alto poder adquisitivo. Cuenta con hoteles boutique de 5 estrellas Gran Lujo ubicados en antiguos cigarrales (fincas señoriales señeras) con vistas panorámicas al casco histórico, como el Cigarral de las Mercedes o el Eurostars Palacio Buenavista. Su gastronomía de vanguardia destaca por restaurantes galardonados como Iván Cerdeño (dos Estrellas Michelin). El municipio sirve como nodo logístico para la organización de monterías de alto standing en fincas fortificadas de la provincia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','lujo','Turismo de lujo','Histórica villa que atrae a la nobleza europea y a empresarios de primer nivel que buscan el concepto "lujo rústico" y desconexión total. El municipio destaca por sus palacios y casas señoriales fortificadas dentro del conjunto monumental, muchas de ellas rehabilitadas para el alquiler vacacional de ultra-lujo con servicios de conserjería a medida. Su entorno rural alberga dehesas privadas exclusivas dedicadas a la ganadería de reses bravas y al turismo ecuestre premium, complementado con una.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10105','lujo','Turismo de lujo','El oasis verde del norte extremeño preferido por las grandes fortunas que huyen de la exposición pública. Su pilar es el Parador de Carlos V, un castillo-palacio histórico de alta gama, rodeado de fincas residenciales blindadas y ocultas en la naturaleza de la comarca de La Vera. Cuenta con helipuertos privados en propiedades particulares y servicios de experiencias de naturaleza exclusivas (rutas en todoterreno VIP, avistamiento privado de fauna y chefs a domicilio de cocina de autor).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','lujo','Turismo de lujo','El epicentro internacional del enoturismo de ultra-lujo en la Rioja Alavesa. Su infraestructura premium orbita alrededor de la icónica Bodega de los Herederos del Marqués de Riscal y su hotel de 5 estrellas Gran Lujo, el Hotel Marqués de Riscal, A Luxury Collection Hotel, diseñado por el célebre arquitecto Frank Gehry. Este complejo cuenta con helipuerto privado, un spa de vinoterapia de alta gama operado por firmas internacionales y el restaurante Marqués de Riscal (con Estrella Michelin). El municipio atrae a coleccionistas de vino y fortunas globales durante todo el año.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','lujo','Turismo de lujo','Nodo histórico del Camino de Santiago que ha desarrollado una infraestructura premium de baja intensidad pero muy exclusiva. Alberga hoteles boutique de diseño vanguardista orientados al bienestar y la relajación de alto standing, integrados en la arquitectura tradicional o el entorno natural. Su oferta gastronómica destaca por asadores y restaurantes de cocina navarra.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','lujo','Turismo de lujo','Aunque el municipio de Cartagena abarca una gran riqueza arqueológica y un puerto militar e histórico, su puntuación premium se dispara gracias al complejo residencial y deportivo La Manga Club (en el entorno de Los Belones). Es uno de los resorts deportivos más exclusivos de Europa, dotado del hotel de 5 estrellas Grand Hyatt La Manga Club Golf & Spa. Cuenta con tres campos de golf de nivel campeonato, un centro de tenis con 28 pistas de primer nivel mundial (utilizado por selecciones internacionales), campos de fútbol profesionales y villas residenciales privadas con seguridad perimetral militarizada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','lujo','Turismo de lujo','El corazón geográfico y de alojamiento premium de la Ribeira Sacra. Su infraestructura exclusiva se cimienta en el Palacio de Sober, un pazo del siglo VII reconvertido en un hotel de 5 estrellas rodeado de jardines señoriales y un spa acristalado de alta gama. El municipio destaca por el turismo náutico fluvial exclusivo, ofreciendo catamaranes y yates privados de alquiler para recorrer los Cañones del Sil, combinado con visitas privadas a bodegas de viticultura heroica orientadas a inversores internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','lujo','Turismo de lujo','El epicentro indiscutible del esquí VIP en España, localizado en el Valle de Arán y vertebrado por la estación de Baqueira Beret. Cuenta con núcleos ultraexclusivos como Baqueira 1500 y las urbanizaciones privadas de Tanau y Val de Ruda, que ofrecen acceso directo a pistas ("ski-in/ski-out") y residencias de alta montaña propiedad de la familia real, aristócratas y grandes empresarios. Su infraestructura incluye zonas VIP y salones privados en pistas, helipuertos operativos para traslados y heliesquí, tiendas de equipamiento técnico premium y el hotel de 5 estrellas Eurostars Royal Tanau. La oferta culinaria y de ocio "aprèsski" destaca por una altísima densidad de restaurantes de alta cocina aranesa y marisquerías exclusivas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','lujo','Turismo de lujo','Uno de los municipios con la mayor renta per cápita de Cataluña y el principal bastión residencial premium de la periferia de Barcelona. Su infraestructura destaca por urbanizaciones fortificadas de baja densidad como Valldoreix y Mirasol, caracterizadas por mansiones contemporáneas de máxima seguridad. Alberga el histórico Club de Golf Sant Cugat (fundado en 1914, con estrictos derechos de admisión) y prestigiosos clubes de tenis y equitación privados. Su tejido urbano cuenta con centros médicos privados de alta gama, colegios internacionales y una selecta oferta de restauración y comercio prémium enfocada al residente de alto standing.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','lujo','Turismo de lujo','Exclusivo refugio residencial y vinícola situado en la comarca del Maresme, a escasos minutos de Barcelona. Es el destino predilecto de empresarios que buscan privacidad con vistas al mar dentro de urbanizaciones privadas de alta seguridad como Alella Park. Su infraestructura premium se vincula a su histórica tradición vitivinícola (D.O. Alella), con bodegas boutique que ofrecen catas privadas y experiencias.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','lujo','Turismo de lujo','Ciudad Patrimonio de la Humanidad que ha desarrollado un sólido nicho de turismo premium cultural y del "oro líquido" (aceite de oliva virgen extra de alta gama). Su infraestructura cuenta con el histórico Palacio de Úbeda, un hotel de 5 estrellas Gran Lujo ubicado en un palacio renacentista del siglo XVI, dotado de termas y servicios de conserjería personalizada. El municipio es pionero en el "oleoturismo" de lujo, ofreciendo visitas privadas en helicóptero a fincas de olivos milenarios, catas exclusivas dirigidas por maestros catadores internacionales y una gastronomía Michelin de vanguardia que reinterpreta la cocina tradicional jiennense.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','lujo','Turismo de lujo','Término municipal que alberga el núcleo residencial y comercial de la Estación de Esquí de Sierra Nevada (Pradollano). Es el destino invernal de referencia del sur de Europa para perfiles de alto poder adquisitivo. Su planta hotelera premium destaca por el hotel de 5 estrellas Lodge Ski & Spa (miembro de Leading Hotels of the World), un exclusivo refugio de madera de estilo alpino con servicio de mayordomía, club infantil VIP y zonas "ski-out". Dispone de villas de alta montaña blindadas, servicios de alquiler de jets de nieve privados, terrazas "après-ski" premium con champañerías y restaurantes de alta cocina mediterránea en altitud.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','lujo','Turismo de lujo','El baluarte del "lujo lento" y la discreción absoluta en la isla de Menorca. Su puerto histórico está adaptado para recibir yates de eslora media y alta, rodeado de una refinada oferta culinaria de producto marítimo local. El casco histórico alberga espectaculares casas palacio de la antigua nobleza menorquina, reconvertidas en hoteles boutique de 5 estrellas con spas privados excavados en roca viva (como el Can Faustino). Las zonas rústicas del municipio esconden "llocs" (fincas agrícolas tradicionales) transformados en agroturismos de ultra-lujo y villas aisladas con acceso restringido a calas vírgenes.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','lujo','Turismo de lujo','La capital histórica del vino de Rioja. Su infraestructura premium se concentra en el Barrio de la Estación, la mayor densidad de bodegas centenarias del mundo (Muga, Viña Tondonia, CVNE). Estas firmas ofrecen salones de catas privados para grandes coleccionistas internacionales, helipuertos y clubes de membresía exclusiva. Su planta hotelera se ha sofisticado con la apertura de hoteles boutique de alta gama en edificios históricos y palacetes. La oferta gastronómica incluye asadores de élite y restaurantes de alta cocina que maridan menús vanguardistas con añadas históricas exclusivas que no se encuentran en el mercado regular.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','lujo','Turismo de lujo','El refugio del lujo alpino y gastronómico de la región, situado a los pies de la Sierra de la Demanda. Este municipio destaca por un turismo selecto y discreto de alto poder adquisitivo. Su gran pilar de infraestructura premium es el hotel y restaurante El Portal de Echaurren (dos Estrellas Michelin), un referente de la alta cocina española dirigido por el chef Francis Paniego. El pueblo cuenta con hoteles boutique de alta gama, tiendas de artesanía textil de lujo internacional (mantas de Ezcaray, proveedoras de grandes firmas de moda) y urbanizaciones residenciales integradas de baja densidad.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','lujo','Turismo de lujo','Destino histórico del norte de la isla que atrae a la aristocracia, artistas y magnates internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07020','lujo','Turismo de lujo','El epicentro del "lujo descalzo" y la arquitectura de piedra tradicional en el sureste de Mallorca. Atrae a un perfil de comprador internacional de alto standing que busca total discreción. Su infraestructura premium incluye el Puerto de Cala d''Or (marina con amarres deportivos premium y servicios náuticos VIP) y urbanizaciones exclusivas colgadas sobre acantilados. En su entorno rural se esconden agroturismos de 5 estrellas y fincas privadas con helipuertos. Cuenta con acceso a playas protegidas y vírgenes como Cala Mondragó, idóneas para el fondeo de yates privados.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','lujo','Turismo de lujo','Nota de enfoque regional: En el corazón de la comarca del Ribeiro, este entorno se ha posicionado en el turismo premium de bienestar y enoturismo selecto. Su infraestructura destaca por los balnearios de aguas termales mineromedicinales transformados en complejos hoteleros de alta gama, como el Eurostars Monumento Monasterio de San Clodio. Cuenta con bodegas boutique de producción limitada que organizan experiencias de cata privadas para inversores internacionales y chefs privados que reinterpretan la cocina tradicional gallega con producto km 0 de altísimo nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','lujo','Turismo de lujo','Histórica villa nobiliaria e industrial que mantiene intacto su estatus de destino residencial de la alta sociedad española. Su infraestructura patrimonial de primer nivel incluye el Capricho de Gaudí y el Palacio de Sobrellano. Su planta inmobiliaria premium consta de palacetes decimonónicos frente al mar y villas fortificadas en la zona de la playa de Oyambre. Dispone de un puerto deportivo histórico adaptado a embarcaciones recreativas medianas, y su entorno inmediato ofrece campos de golf de prestigio y restaurantes de alta cocina marinera especializada en marisco del Cantábrico de lonja.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','lujo','Turismo de lujo','Transformado de meca del viento a epicentro del "boho-chic luxury" y el eco-lujo en el Sur de Europa. Su infraestructura premium huye del gigantismo y se centra en hoteles boutique de ultra-lujo y máxima discreción como el Hotel Valdevaqueros o Meliá Zahara Atlanterra (en su área de influencia). Destaca por sus villas de diseño contemporáneo integradas en los acantilados de la zona de la duna de Bolonia y Atlanterra, con helipuertos privados y seguridad VIP. Cuenta con una selecta oferta de clubes de playa premium (como Tumbao o Volare) y experiencias exclusivas de avistamiento privado de cetáceos en yates chárter de alta gama.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','lujo','Turismo de lujo','Pueblo blanco fortificado que atrae a la élite cultural y financiera internacional que busca el "lujo descalzo" en el interior de la costa. Su pilar fundamental de infraestructura premium es el Montenmedio Golf & Country Club, que alberga instalaciones hípicas de nivel olímpico mundial (sede del Sunshine Tour, el circuito hípico más importante de Europa) y un campo de golf privado. El casco histórico esconde casas-palacio reformadas como hoteles boutique de alta gama y una gastronomía de autor liderada por restaurantes exclusivos que fusionan la cocina árabeandaluza con el atún rojo de almadraba.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','lujo','Turismo de lujo','Enclave fronterizo estratégico posicionado con solidez en el mercado residencial de alta gama y turismo deportivo. Su infraestructura premium destaca por el complejo Isla Canela Old Course y el campo de campeonato Valle Guadiana Links, que ofrece un recorrido de 18 hoyos con vistas panorámicas espectaculares al río Guadiana navegable y al litoral atlántico. Dispone de exclusivos centros hípicos privados integrados en las marismas para paseos de alta escuela ecuestre, promociones inmobiliarias blindadas de villas inteligentes con seguridad perimetral 24/7 y conexiones rápidas fluviales y aéreas para transfers en jets privados hacia el Algarve portugués.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30037','lujo','Turismo de lujo','Municipio de interior que ha desarrollado un potente ecosistema residencial y turístico premium basado en resorts de golf cerrados. Su mayor infraestructura es el Mar Menor Golf Resort y los complejos adyacentes administrados por firmas de lujo internacionales. Alberga hoteles de 5 estrellas y un denso parque inmobiliario de villas de diseño vanguardista con seguridad privada perimetral militarizada. Sus servicios premium incluyen lagunas artificiales privadas de agua cristalina para deportes náuticos exclusivos, spas médicos de alta gama y helipuertos para clientes VIP internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','lujo','Turismo de lujo','El bastión del turismo señorial en el oriente asturiano. Su planta de infraestructuras premium destaca por la reconversión de antiguas casonas de indianos y palacios barrocos en hoteles boutique de 5 estrellas y alojamientos de alta gama aislados. Su costa alberga playas de acceso protegido e idóneas para el fondeo discreto de embarcaciones de recreo medianas. Cuenta con el campo municipal de Golf Municipal de Llanes (con una de las panorámicas más exclusivas de la Cornisa Cantábrica) y una red de alta.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02019','lujo','Turismo de lujo','Municipio vinculado al Parque Natural de las Lagunas de Ruidera que esconde un reducto de turismo premium enfocado en la privacidad absoluta. Su infraestructura exclusiva se basa en grandes fincas residenciales e históricos cortijos de caza mayor reconvertidos en alojamientos de ultra-lujo de gestión privada y bajo régimen de alquiler íntegro para dignatarios y empresarios extranjeros. Dispone de zonas de helipuerto autorizadas y ofrece experiencias personalizadas como rutas ecuestres de pura raza y catas privadas con chefs con Estrella Michelin desplazados en exclusiva al complejo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35014','lujo','Turismo de lujo','Municipio norteño que concentra el turismo de alto standing de la isla, vertebrado por la localidad de Corralejo. Su infraestructura premium destaca por el hotel de 5 estrellas Gran Lujo Gran Hotel Bahía Real (con su icónico spa con vistas a la isla de Lobos). Dispone de villas de diseño vanguardista construidas sobre coladas volcánicas con máxima privacidad en zonas residenciales exclusivas. El puerto deportivo de Corralejo sirve como base para chárters privados de yates de gran eslora que navegan por el estrecho de La Bocayna, complementado con una gastronomía gourmet especializada en pescados atlánticos y quesos artesanos premiados a nivel mundial.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','lujo','Turismo de lujo','Histórico Real Sitio de la Sierra de Guadarrama y refugio señorial de la alta burguesía madrileña. Su fisonomía está marcada por el imponente Monasterio de El Escorial. Su infraestructura premium cuenta con hoteles boutique de alta gama ubicados.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','lujo','Turismo de lujo','Exclusivo bastión residencial y deportivo de la periferia de Bilbao, preferido por grandes directivos, empresarios y futbolistas de élite que buscan huir de la exposición pública. Su infraestructura premium gira en torno a la urbanización privada La Bilbaína (Laukariz), un complejo residencial fortificado con avanzados sistemas de seguridad y patrullas 24/7. En su corazón alberga el Club de Campo Laukariz, dotado de un campo de golf de campeonato de 27 hoyos diseñado por el prestigioso arquitecto Robert Putman, además de un club social con restaurantes de alta cocina vasca y pistas de tenis y pádel privadas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','lujo','Turismo de lujo','La capital del vino y del cava de Extremadura, posicionada en el segmento del enoturismo premium y el estilo de vida señorial de interior. Su infraestructura está orientada a la élite del sector.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','lujo','Turismo de lujo','Municipio costero íntimamente ligado al turismo de ultra-lujo del norte de España a través de la icónica Isla de La Toja. Esta isla privada constituye un búnker de exclusividad residencial y de bienestar que alberga el legendario Eurostars Gran Hotel La Toja (un balneario de 5 estrellas histórico que ha hospedado a jefes de Estado y aristocracia europea). Su infraestructura premium incluye un campo de golf privado de 9 hoyos al borde del mar, el Casino de La Toja, helipuertos operativos, un club náutico para embarcaciones de recreo y exclusivas urbanizaciones de chalets blindados con vistas directas a la Ría de Arousa, respaldados por una gastronomía marinera con Estrellas Michelin (como el restaurante Culler de Pau en sus inmediaciones).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18012','lujo','Turismo de lujo','Histórico refugio de veraneo e invierno de la alta burguesía barcelonesa en el pirineo gerundense. Su infraestructura residencial premium destaca por los palacetes decimonónicos situados alrededor del estanque y la urbanización de ultra-lujo Real Club de Golf de Cerdanya. Cuenta con el hotel de 5 estrellas Chalet del Golf y villas de diseño alpino blindadas con sistemas de alta seguridad. El municipio dispone de un helipuerto operativo para conexiones rápidas con Barcelona y Andorra, tiendas multimarca de alta costura internacional y una selecta gastronomía de montaña de autor enfocada a un perfil de visitante corporativo e institucional.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43038','lujo','Turismo de lujo','El bastión del turismo gourmet y náutico premium en la Costa Daurada. Su infraestructura clave es el Club Nàutic Cambrils, una marina moderna dotada de amarres de gran calado para yates deportivos y servicios de chárter VIP de eslora media-alta. El municipio destaca a nivel nacional por su alta densidad gastronómica, liderada por restaurantes galardonados con Estrellas Michelin (como Can Bosch y Rincón de Diego). Su planta hotelera incluye complejos boutique de alta gama enfocados al bienestar, rodeados de exclusivas promociones residenciales de chalets de diseño contemporáneo frente al mar.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','lujo','Turismo de lujo','Histórica villa fortificada que funciona como el gran pulmón del turismo señorial e inmobiliario rural de la aristocracia sevillana. Su infraestructura premium se basa en la reconversión de casas palacio barrocas y mudéjares en hoteles boutique de alta gama, destacando el Parador de Carmona (ubicado en un alcázar del siglo XIV). Su entorno rústico alberga históricas haciendas de olivar y fincas de miles de hectáreas fortificadas de uso privado, equipadas con helipuertos, plazas de toros privadas e instalaciones hípicas de pura raza española para el uso exclusivo de dignatarios y empresarios globales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14073','lujo','Turismo de lujo','Municipio enclavado en Sierra Morena occidental, consolidado como un destino de ultra-lujo discreto especializado en el turismo cinegético internacional de alta gama. Carece de infraestructura urbana.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','lujo','Turismo de lujo','Nota de enfoque geográfico: Aunque el núcleo urbano central se asocia al turismo de masas, el término municipal y su linde inmediata con Finestrat albergan un búnker de exclusividad en las faldas de la sierra. Su infraestructura de súper-lujo está capitaneada por el resort de 5 estrellas Gran Lujo Asia Gardens Hotel & Thai Spa (miembro de Leading Hotels of the World), un oasis balinés blindado con máxima privacidad y helipuerto operativo. La zona cuenta con el campo de golf Villaitana (diseñado por Jack Nicklaus) y exclusivas urbanizaciones de mansiones inteligentes de diseño vanguardista con seguridad privada 24/7.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','lujo','Turismo de lujo','Destino costero de marcado carácter aristocrático que posee la playa más larga del País Vasco, flanqueada por palacetes y mansiones históricas residenciales de altísima cotización. Su infraestructura premium destaca por el Real Club de Golf de Zarautz (un campo histórico fundado en 1916 con vistas directas al mar Cantábrico). El municipio cuenta con una planta hotelera boutique de alta gama y un posicionamiento culinario mundial encabezado por el emblemático restaurante y hotel de Karlos Arguiñano, complementado con escuelas de surf premium personalizadas para perfiles VIP y servicios de conserjería náutica exclusiva.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28127','lujo','Turismo de lujo','Municipio residencial y de negocios con una de las rentas per cápita más elevadas de la región. Su infraestructura de lujo destaca por urbanizaciones exclusivas y fortificadas como Las Matas o El Golf, organizadas en torno al Club de Golf Las Rozas. Su gran pilar comercial premium es Las Rozas Village, un complejo de "shopping" outlet de lujo que reúne las principales firmas de alta costura internacionales (Armani, Gucci, Loewe) con servicios de conserjería VIP, "personal shoppers" y salas privadas para clientes de alto standing. Dispone de centros deportivos de alto rendimiento y clínicas estéticas de primer nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28080','lujo','Turismo de lujo','Bastión residencial caracterizado por un urbanismo de baja densidad y máxima seguridad en urbanizaciones como Roza Martín o Monte del Pilar. Cuenta con el prestigioso Club de Campo Villa de Madrid en su zona de influencia y prestigiosos clubes de tenis y equitación privados. Su arteria principal, la Gran Vía, alberga boutiques.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47139','lujo','Turismo de lujo','El epicentro del vino blanco de alta gama de la meseta norte. Su infraestructura premium radica en bodegas de renombre internacional (como Bodegas José Pariente o Marqués de Riscal en su vertiente de blancos) que cuentan con salas de catas privadas subterráneas e históricas preparadas para inversores y coleccionistas mundiales. Dispone de hoteles boutique de alta gama integrados en fincas vitivinícolas y restaurantes de alta cocina castellana de vanguardia que atraen a empresarios de la capital en busca de retiros discretos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12115','lujo','Turismo de lujo','Histórico municipio zamorano posicionado internacionalmente gracias a la potencia de sus vinos tintos premium. Alberga proyectos vinícolas de ultra-lujo respaldados por grandes capitales internacionales (como el grupo LVMH con Bodega Numanthia o la familia Álvarez con Pintia). Estas bodegas ofrecen experiencias exclusivas de helitransporte para clientes VIP que aterrizan directamente en las fincas, visitas privadas a viñedos prefiloxéricos y catas personalizadas de barricas históricas que no salen al mercado general.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','lujo','Turismo de lujo','El oasis residencial y de desconexión premium en la conocida como "Isla Bonita". Este municipio destaca por un turismo residencial de ultra-lujo y bajísima densidad que busca el anonimato absoluto. En sus laderas se esconden villas de diseño eco-vanguardista y antiguas haciendas plataneras rehabilitadas con presupuestos multimillonarios. Dispone de helipuertos privados en propiedades particulares para transfers rápidos y ofrece servicios a medida de astroturismo VIP (observación privada de estrellas con astrónomos personales en el entorno del Roque de los Muchachos).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','lujo','Turismo de lujo','El refugio del turismo de interior de alta gama en el occidente andaluz, en pleno Parque Natural Sierra de Aracena y Picos de Aroche. Su infraestructura premium destaca por hoteles boutique y de bienestar de 5 estrellas como el Hotel Convento Aracena & Spa. El municipio es la capital mundial de la cultura del cerdo ibérico de bellota de máxima pureza (D.O.P. Jabugo en su zona de influencia), ofreciendo a un perfil sibarita e internacional experiencias de catas privadas en bodegas centenarias de jamón, dehesas privadas fortificadas de acceso restringido y restauración gourmet especializada en producto micológico y carnes selectas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','lujo','Turismo de lujo','Histórica villa marinera de las Rías Baixas consolidada como uno de los puertos deportivos de referencia del Atlántico europeo. Su infraestructura estrella es el Monte Real Club de Yates de Baiona, una marina de gran prestigio que organiza regatas internacionales y ofrece amarres de gran calado para embarcaciones exclusivas de alta eslora. Cuenta con el Parador de Baiona, ubicado en la espectacular fortaleza amurallada de Monterreal, urbanizaciones residenciales de alto standing con vistas a las Islas Cíes y una oferta gastronómica especializada en marisco de lonja gallego elevado a la alta cocina.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','lujo','Turismo de lujo','Histórica capital del vino de Jerez, el brandy, el caballo cartujano y el flamenco señorial. Su planta de alojamiento VIP se ha transformado radicalmente con palacios decimonónicos reconvertidos en hoteles de 5 estrellas Gran Lujo, destacando el Hotel Palacio María Luisa. Su infraestructura premium cuenta con bodegas de fama mundial (como Álvaro Domecq, Tradición o González Byass) que albergan colecciones de arte privadas de nivel de museo, sacristías de vinos centenarios accesibles solo bajo invitación exclusiva, y helipuertos. Dispone del Club de Golf Sherry Golf Jerez y de espectaculares fincas rústicas fortificadas donde se crían caballos de pura raza española, atrayendo a la aristocracia internacional y a grandes fortunas. Su gastronomía cuenta con estrellas Michelin (como Mantúa y LÚ Cocina y Alma).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','lujo','Turismo de lujo','El epicentro del turismo premium y residencial de la Costa Tropical granadina. Su gran baluarte es la urbanización de ultra-lujo Marina del Este, un búnker inmobiliario donde las mansiones de diseño vanguardista se cuelgan de los acantilados de Punta de la Mona con sistemas de alta seguridad y total privacidad. Alberga el puerto deportivo Puerto Deportivo Marina del Este, una marina de gran calado encajada en un paraje natural que ofrece amarres privados para yates de gran eslora y servicios de chárter VIP. Dispone de hoteles de 5 estrellas enfocados al bienestar y spas de lujo, complementados con restaurantes de alta cocina mediterránea especializados en marisco y frutos tropicales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','lujo','Turismo de lujo','Nota de enfoque comarcal: Estos municipios vecinos representan el "Triángulo de Oro" del Bajo Ampurdán interior, el refugio predilecto de la alta burguesía catalana que busca el concepto de "toscana catalana" con máxima discreción. Su infraestructura premium huye del turismo masivo, basándose en la rehabilitación de castillos medievales, masías fortificadas y masías de piedra transformadas en hoteles boutique de 5 estrellas o propiedades de alquiler íntegro con tarifas multimillonarias. El entorno cuenta con el exclusivo Golf Playa de Pals (fundado en 1966) y restaurantes de alta cocina ampurdanesa de vanguardia que surten a un perfil de visitante corporativo e institucional muy selecto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','lujo','Turismo de lujo','Nota de ampliación estructural: Este enclave del litoral sur murciano se consolida en el mercado premium internacional por su baja densidad residencial. Su infraestructura exclusiva se concentra en la ladera de Cabo Cope, con promociones de villas inteligentes equipadas con domótica avanzada y piscinas infinitas. Se beneficia de servicios náuticos VIP en el Puerto Deportivo Juan Montiel, escuelas de buceo con instructores personalizados para perfiles VIP y una selecta gastronomía mediterránea km 0 especializada en el preciado calamar de potera local.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90648','lujo','Turismo de lujo','El oasis del enoturismo premium y el estilo de vida señorial de interior en Mallorca. Su fisonomía urbana destaca por las espectaculares casas de piedra de la antigua aristocracia rural de la isla. Su infraestructura de lujo está íntimamente ligada a sus bodegas históricas amparadas bajo la D.O. Binissalem (como Bodegas José L. Ferrer o Tianna Negre), las cuales ofrecen espacios de cata privados subterráneos, menús maridados preparados por chefs privados y experiencias de recolección de uva personalizadas para coleccionistas internacionales. El municipio cuenta con agroturismos de 5 estrellas aislados que garantizan un anonimato absoluto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43055','lujo','Turismo de lujo','La capital del Priorat funciona como el centro operativo del enoturismo de ultra-lujo en una de las regiones vinícolas más cotizadas del mundo. Su infraestructura premium destaca por hoteles boutique orientados al diseño y bodegas que ofrecen catas privadas de vinos de culto para coleccionistas internacionales, con helipuertos adaptados en fincas rústicas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','lujo','Turismo de lujo','Histórico refugio costero de las grandes estrellas del deporte y empresarios de Barcelona. Su infraestructura destaca por la urbanización blindada de alta seguridad Bellamar, caracterizada por mansiones de diseño vanguardista colgadas sobre el mar. Cuenta con el cercano Port Ginesta, una marina preparada para yates de gran calado, y exclusivas escuelas de tenis privadas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04029','lujo','Turismo de lujo','Municipio costero posicionado en el turismo deportivo y residencial premium. Alberga el complejo Valle del Este Golf Resort, un oasis deportivo con un campo de golf de campeonato de 18 hoyos, hotel de alta gama y spa médico. Dispone de urbanizaciones privadas de baja densidad con seguridad perimetral avanzadísima y clubes de playa exclusivos frente al litoral.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','lujo','Turismo de lujo','Un destino de singularidad premium absoluta basado en el turismo ecuestre de alto standing y el aislamiento en Doñana. Sus calles de arena esconden casas-palacio privadas de grandes terratenientes y aristócratas. Cuenta con el hotel boutique de 5 estrellas Palacio Doñana, helipuertos civiles autorizados y servicios de safaris privados VIP organizados en exclusiva dentro de la reserva nacional.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','lujo','Turismo de lujo','Destino de la Costa Blanca caracterizado por sus mansiones de diseño contemporáneo situadas en los acantilados de las urbanizaciones Maryvilla y Canuta. Dispone del Real Club Náutico de Calpe, especializado en yates deportivos de media y gran eslora, y una selecta gastronomía de alta gama que incluye restaurantes galardonados con Estrellas Michelin.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03020','lujo','Turismo de lujo','Enclave residencial de baja densidad preferido por fortunas centroeuropeas. Su infraestructura premium destaca por el puerto deportivo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50272','lujo','Turismo de lujo','El principal nodo residencial premium de la periferia de Zaragoza. Su infraestructura se concentra en urbanizaciones privadas y cerradas de chalets de alta gama con estrictos controles de acceso. Cuenta con clubes de tenis privados, centros ecuestres y un entorno de alta seguridad preferido por directivos industriales y empresarios que buscan la desconexión total a pocos minutos de la capital.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31068','lujo','Turismo de lujo','Pequeño municipio ribero que destaca por albergar infraestructura de bienestar e hidroterapia premium. Su complejo termal y deportivo atrae a un perfil de turismo de salud muy selecto. Dispone de fincas señoriales de alquiler vacacional exclusivo, rodeadas de olivares milenarios donde se organizan experiencias gastronómicas privadas de recolección y catas de aceites premium.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','lujo','Turismo de lujo','El gran referente del termalismo histórico y el bienestar médico discreto en la cornisa cantábrica. Su infraestructura premium se fundamenta en el célebre Gran Hotel Balneario de Puente Viesgo, un complejo de alta gama cuyas aguas mineromedicinales termales son utilizadas para tratamientos terapéuticos y de salud avanzada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47010','lujo','Turismo de lujo','Histórica villa marinera de veraneo aristocrático. Su planta hotelera premium cuenta con palacios históricos reconvertidos en hoteles boutique de alta gama, como el Palacio Oxangoiti. Dispone de un puerto deportivo adaptado para veleros de recreo de eslora media-alta y una cotizada oferta residencial en primera línea de costa, libre del turismo masivo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','lujo','Turismo de lujo','El refugio del lujo bohemio e intelectual más cotizado del norte del Mediterráneo. Su aislamiento geográfico natural garantiza la máxima privacidad a grandes fortunas y celebridades mundiales. Carece de grandes cadenas hoteleras o autopistas, pero su infraestructura destaca por mansiones de arquitectura racionalista ocultas en los acantilados de Portlligat y el Parque Natural del Cap de Creus. Su bahía es el fondeadero estival más exclusivo para megayates de gran eslora que buscan discreción, complementado con restaurantes de alta cocina especializados en producto marino local y galerías de arte privadas de alto standing.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','lujo','Turismo de lujo','Núcleos costeros del Baix Empordà que concentran el veraneo tradicional de la alta burguesía catalana. Su fisonomía destaca por exclusivas fincas residenciales en primera línea de mar con.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','lujo','Turismo de lujo','Valle rodeado por la Sierra de Tramuntana que combina el encanto histórico con la infraestructura premium internacional. Su bahía alberga el Port de Sóller, una marina protegida que da cobijo a yates deportivos y ofrece servicios de chárter VIP de gran eslora. Su planta hotelera cuenta con el majestuoso Jumeirah Port Soller Hotel & Spa, establecimiento de 5 estrellas Gran Lujo suspendido sobre un acantilado marino. Dispone de palacetes modernistas reconvertidos en hoteles boutique en su casco urbano y exclusivas fincas de olivar de alquiler vacacional ultra-privado.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46111','lujo','Turismo de lujo','Uno de los grandes bastiones del golf tradicional y residencial de alta gama en la provincia. Su infraestructura premium gira por completo en torno a la urbanización privada El Bosque, un complejo blindado con estrictos controles de accesos y patrullas de seguridad 24/7. En su corazón alberga el prestigioso Club de Golf El Bosque, un campo de campeonato de 18 hoyos diseñado por el célebre arquitecto Robert Trent Jones Sr. [Image 1.5.3], que se adapta a las ondulaciones del terreno y exige la máxima precisión. La zona cuenta con mansiones inteligentes de diseño contemporáneo, clubes de tenis privados, centros hípicos de alto rendimiento en su periferia y una selecta restauración de cocina mediterránea de vanguardia orientada al exigente público corporativo local.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37344','lujo','Turismo de lujo','Municipio de la comarca del Campo Charro que destaca como un destino oculto de ultra-lujo rural y turismo cinegético y ganadero de alto standing. Su territorio está jalonado por extensas e históricas dehesas de encinas y fincas fortificadas de miles de hectáreas, propiedad de la aristocracia y grandes empresarios españoles. Estas propiedades cuentan con cortijos señoriales reformados con presupuestos millonarios de alquiler íntegro exclusivo, equipados con helipuertos privados autorizados, plazas de tienta particulares y servicios de chefs con Estrella Michelin bajo demanda.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','lujo','Turismo de lujo','Ciudad Patrimonio de la Humanidad que, junto a su vecina Úbeda, vertebra el turismo cultural y del "oro líquido" de alta gama en el interior andaluz. Su infraestructura premium se basa en la reconversión de palacios renacentistas y casas solariegas en hoteles boutique de alta gama dotados de circuitos termales exclusivos. El municipio destaca por sus experiencias de oleoturismo premium, ofreciendo visitas guiadas privadas a almazaras de diseño arquitectónico vanguardista donde se producen los aceites de oliva virgen extra más premiados del mundo, con catas personalizadas para inversores internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','lujo','Turismo de lujo','Histórico enclave residencial de la sierra madrileña que combina naturaleza con una altísima renta per cápita. Su infraestructura premium destaca por urbanizaciones fortificadas como Los Peñascales o Las Marías, compuestas por mansiones de diseño vanguardista y máxima privacidad. Alberga el icónico Casino Gran Madrid.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','lujo','Turismo de lujo','Uno de los municipios más exclusivos de la costa barcelonesa, preferido por grandes empresarios en busca de discreción marítima. Su infraestructura premium destaca por la urbanización residencial fortificada Supermaresme, un búnker de alta seguridad con cámaras térmicas y patrullas constantes donde se ubican mansiones multimillonarias. Cuenta con el Club de Golf Llavaneres (fundado en 1945 con vistas panorámicas al Mediterráneo), instalaciones hípicas de alto nivel y el puerto deportivo Port Balís, dotado de amarres para yates de gran eslora, helipuerto y restaurantes gourmet.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','lujo','Turismo de lujo','El núcleo de desarrollo residencial y turístico premium de la Costa Tropical granadina. Su infraestructura de lujo se concentra en el área de Playa Granada, históricamente elegida por familias reales europeas para sus retiros estivales secretos. Alberga el campo de golf Los Moriscos Golf Club, un recorrido de 18 hoyos situado en.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','lujo','Turismo de lujo','Capital de la Rioja Alavesa y uno de los destinos enoturísticos de ultra-lujo más importantes de Europa. Su infraestructura está jalonada por bodegas de diseño arquitectónico vanguardista mundial como Bodegas Ysios (diseñada por Santiago Calatrava) o Bodegas Campillo. Estos complejos vinícolas ofrecen salas de catas privadas y santuarios de barricas exclusivas para inversores y personalidades internacionales de alto poder adquisitivo. Cuenta con hoteles boutique de alta gama integrados en sus murallas medievales, spas de vinoterapia y alta gastronomía vasca tradicional elevada al formato gourmet.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','lujo','Turismo de lujo','Antigua capital que alberga un desarrollo residencial y de alojamiento premium integrado en la estética volcánica de César Manrique. Su infraestructura de lujo destaca por el hotel de 5 estrellas Paradisus Salinas Lanzarote, célebre por su arquitectura y jardines botánicos protegidos. Cuenta con el campo de golf Costa Teguise Golf (diseñado por John Harris sobre lava.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90022','lujo','Turismo de lujo','El último reducto del auténtico "barefoot luxury" y el aislamiento absoluto en el norte de Ibiza. Es el municipio más virgen de la isla y destaca por una infraestructura de ultra-lujo integrada de forma invisible en la naturaleza. Alberga agroturismos de 5 estrellas Gran Lujo de renombre mundial como Atzaró Agroturismo Hotel o el exclusivo resort Six Senses Ibiza en Cala Xarraca, referente mundial en bienestar premium, sostenibilidad y tratamientos de longevidad. Su territorio está copado por fincas rústicas milenarias fortificadas y de alquiler íntegro con helipuertos privados ocultos entre pinares, donde perfiles corporativos globales e institucionales buscan un anonimato total. Sus calas protegidas (como Benirràs o Cala de Sant Vicent) son fondeaderos predilectos para yates de gran eslora que huyen de la exposición mediática de las grandes marinas del sur.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90956','lujo','Turismo de lujo','Municipio de la costa vizcaína reconvertido en un enclave residencial y de ocio deportivo premium para la élite de Bilbao. Su infraestructura destaca por urbanizaciones exclusivas de chalets de diseño de vanguardia construidos sobre acantilados con vistas directas al mar Cantábrico. El mercado inmobiliario premium de la zona ha crecido exponencialmente gracias a su conectividad y privacidad. Cuenta con escuelas de surf con servicios VIP personalizados, instructores privados para grandes empresarios y deportistas, y un ecosistema gastronómico que fusiona los asadores tradicionales vascos con técnicas culinarias modernas de primer nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10131','lujo','Turismo de lujo','Municipio que funciona como el centro operativo y logístico del turismo cinegético de alto standing en el noreste de Extremadura. Su entorno está rodeado por inmensas dehesas privadas y fincas fortificadas de miles de hectáreas, propiedad de terratenientes históricos y magnates internacionales. Estas propiedades privadas están dotadas de pabellones de caza de ultra-lujo, sistemas de seguridad perimetral avanzada, helipuertos homologados y pistas de aterrizaje privadas para aeronaves ligeras, atrayendo a la élite financiera durante la temporada de monterías mayores.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','lujo','Turismo de lujo','Municipio cordobés consagrado internacionalmente por la excelencia y sofisticación de su aceite de oliva virgen extra (D.O.P. Baena). Su infraestructura turística premium gira en torno al "oleoturismo" de alta gama, con históricas haciendas palaciegas andaluzas rehabilitadas con presupuestos millonarios para alojar a inversores y compradores internacionales del sector agroalimentario de lujo. Ofrece visitas privadas y catas dirigidas en exclusivas almazaras de diseño, paseos a caballo de pura raza española por los olivares y experiencias gastronómicas privadas con chefs de renombre.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','lujo','Turismo de lujo','La capital histórica del vino Albariño y uno de los epicentros de la hidalguía gallega en las Rías Baixas. Su infraestructura de súper-lujo se asienta en sus espectaculares pazos barrocos (como el Pazo de Fefiñáns), que albergan bodegas privadas donde se realizan catas exclusivas de añadas históricas para coleccionistas internacionales. Cuenta con el Parador de Cambados (antiguo Pazo de Bazán) y una selecta planta de hoteles boutique. Su puerto da soporte a chárters náuticos VIP para recorrer la ría de Arousa de forma privada, complementado con una gastronomía marina de altísimo nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03027','lujo','Turismo de lujo','Distrito costero que concentra una de las mayores infraestructuras de turismo residencial internacional premium de la Costa Blanca Sur. Su joya es el resort residencial cerrado Las Colinas Golf & Country Club, galardonado a nivel europeo, que cuenta con un campo de golf de campeonato de 18 hoyos diseñado por Cabell B. Robinson, un exclusivo Beach Club privado en primera línea de playa, pistas de tenis de alto rendimiento y residencias de ultra-lujo fortificadas. Dispone también de puertos deportivos cercanos y helipuertos para clientes VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','lujo','Turismo de lujo','Municipio histórico de interior costero vinculado al cultivo y exportación de frutos rojos premium a mercados de lujo europeos. Su infraestructura de exclusividad radica en fincas rústicas privadas de gran extensión y casas señoriales restauradas que garantizan el anonimato absoluto. En sus cercanías se despliegan campos de golf integrados en pinares de la Costa de la Luz y zonas residenciales blindadas de baja densidad, complementadas con una gastronomía de autor basada en el marisco de la costa onubense de lonja.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','lujo','Turismo de lujo','El principal bastión residencial de la élite empresarial e industrial de la periferia de Santander. Su infraestructura premium destaca por urbanizaciones cerradas de baja densidad como Mompía y Sancibrián, caracterizadas por mansiones señoriales y chalets de diseño contemporáneo con estrictos sistemas de seguridad privada. El municipio se beneficia de su cercanía inmediata con el campo de golf de la capital y prestigiosos centros ecuestres. Dispone de clínicas de salud privada de alta gama y un litoral protegido con calas exclusivas idóneas para el descanso discreto de perfiles VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','lujo','Turismo de lujo','Sede del Consejo Regulador de la D.O. Ribera del Duero y nodo operativo del enoturismo de alta gama en la provincia de Burgos. Su infraestructura de lujo se fundamenta en bodegas de prestigio mundial que rodean su término municipal, las cuales albergan comedores privados, santuarios de barricas y helipuertos operativos para el traslado directo de grandes inversores e importadores internacionales. Cuenta con hoteles boutique de alta gama integrados en complejos vitivinícolas históricos y una gastronomía castellana gourmet enfocada al maridaje de vinos de coleccionista.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','lujo','Turismo de lujo','El refugio residencial histórico de las grandes fortunas de Gran Canaria y del cuerpo diplomático internacional. Su fisonomía destaca por los palacetes de arquitectura colonial inglesa y las mansiones vanguardistas blindadas del área de Bandama. Su infraestructura deportiva premium incluye el Real Club de Golf de Las Palmas (el club de golf más antiguo de España, fundado en 1891), situado al borde de la caldera volcánica de Bandama. El municipio ofrece un entorno de máxima seguridad, frescor alpino y restaurantes gourmet especializados en alta cocina canaria.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','lujo','Turismo de lujo','Municipio residencial de interior de la costa del Maresme consolidado como un destino de alto standing inmobiliario que garantiza anonimato absoluto a directivos y empresarios. Su infraestructura destaca por urbanizaciones fortificadas en las colinas forestales con vistas panorámicas al mar. El municipio posee una altísima cotización por metro cuadrado y es reconocido por su selecto oasis gastronómico, que reúne restaurantes de alta cocina de autor en masías históricas restauradas con presupuestos millonarios.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','lujo','Turismo de lujo','El bastión residencial e industrial premium por excelencia de la periferia de Oviedo y Gijón. Su infraestructura de exclusividad orbita alrededor de la urbanización privada Soto de Llanera, un complejo cerrado con estrictos controles de acceso y patrullas de seguridad las 24 horas donde residen empresarios, directivos y deportistas de élite. Dispone en sus lindes directas del Club de Campo La Fresneda y de prestigiosos centros ecuestres de alta competición. Su oferta se complementa con helipuertos operativos en sus áreas empresariales y una red de palacios históricos asturianos reconvertidos en sedes de eventos y restauración corporativa VIP de primer nivel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30026','lujo','Turismo de lujo','Municipio costero enfocado en el turismo náutico y residencial premium del litoral sur murciano. Su infraestructura clave de lujo destaca por el Puerto Deportivo de Mazarrón, una marina moderna equipada con amarres de gran calado para yates deportivos, chárters VIP y servicios de mantenimiento naval de alto standing. En sus colinas marítimas se erigen exclusivas urbanizaciones de villas inteligentes con piscinas infinitas y total privacidad frente al mar (como el área de Bolnuevo). Su gastronomía marina premium y la cercanía a campos de golf internacionales elevan notablemente su posicionamiento en el mercado de alta gama europeo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','lujo','Turismo de lujo','Nodo logístico e histórico del interior andaluz que esconde una selecta infraestructura privada orientada al turismo de fincas e inversiones agroalimentarias de alta gama. Su término municipal está rodeado por históricas haciendas de olivar y fincas de caza menor, propiedad de la burguesía industrial, muchas de las cuales han sido rehabilitadas como alojamientos de ultra-lujo de gestión privada y alquiler íntegro exclusivo para directivos. El municipio cuenta con áreas autorizadas de helipuerto y destaca por la producción de aceites de oliva premium de edición limitada dirigidos a mercados internacionales de lujo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','lujo','Turismo de lujo','El máximo exponente del Matarraña, comarca conocida internacionalmente como la "Toscana española". Su infraestructura premium prescinde del gigantismo y se enfoca en el "lujo silencioso" y la desconexión absoluta para perfiles institucionales y corporativos globales. Alberga hoteles boutique de 5 estrellas aislados en la naturaleza, como el exclusivo Solo Houses (un proyecto vanguardista que fusiona arquitectura de diseño mundial con paisajismo virgen). El municipio ofrece servicios de helipuerto privado bajo demanda, rutas ecuestres de alto nivel y una restauración km 0 gourmet altamente cotizada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07001','lujo','Turismo de lujo','Uno de los grandes baluartes turísticos y residenciales del norte de la isla, célebre por su imponente bahía. Su infraestructura premium está capitaneada por Alcúdiamar, un puerto deportivo y botánico de vanguardia con capacidad para embarcaciones de hasta 30 metros de eslora, que ofrece servicios de chárter náutico VIP y amarres de alta seguridad. En su linde residencial destaca la península de Alcanada, una zona hiper-exclusiva que alberga villas de diseño contemporáneo valoradas en millones de euros y el prestigioso Club de Golf Alcanada (diseñado por Robert Trent Jones Jr.), catalogado de forma recurrente como uno de los mejores campos de Europa con vistas directas al mar. Su oferta gastronómica incluye alta cocina de vanguardia y beach clubs de estilo de vida premium.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','lujo','Turismo de lujo','La capital mundial del cava funciona como un núcleo neurálgico de la economía de alto standing e inversiones internacionales en el sector vitivinícola. Su infraestructura de súper-lujo se asienta en bodegas icónicas y centenarias (como Codorníu, Gramona o Recaredo), que cuentan con cavas históricas subterráneas, salones privados de cata y helipuertos operativos en sus fincas para grandes importadores y coleccionistas globales. El municipio ofrece agroturismos de 5 estrellas de diseño minimalista integrados entre los viñedos, servicios de chófer privado y restaurantes de alta cocina mediterránea.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','lujo','Turismo de lujo','Municipio que presume de tener "el mejor clima de Europa" y que ha desarrollado un sólido sector inmobiliario residencial enfocado al turismo premium e internacional de baja densidad. Lejos de la masificación urbana, sus colinas y laderas marítimas albergan exclusivas promociones de villas de lujo inteligentes con piscinas infinitas y vistas panorámicas al mar de Alborán. Se beneficia de su cercanía logística a la marina de Caleta de Vélez para el.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','lujo','Turismo de lujo','Histórica capital pirenaica consolidada como el epicentro de la alta burguesía aragonesa y vasca para el turismo de montaña de alto standing. Su infraestructura destaca por urbanizaciones residenciales de chalets de piedra y madera noble con máxima seguridad privada en la zona de Membrilleras. Cuenta con una planta hotelera boutique.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26007','lujo','Turismo de lujo','El corazón de la economía y el enoturismo premium de la comarca del Bierzo. Su infraestructura exclusiva se cimienta en bodegas de renombre internacional (como Descendientes de J. Palacios) que producen vinos de culto puntuados con las máximas calificaciones mundiales. Estas fincas cuentan con helipuertos operativos para el traslado de inversores internacionales y salas de catas privadas integradas en viñedos de pendientes extremas. El municipio se complementa con alojamientos boutique de alta gama en antiguas casonas de piedra restauradas y una gastronomía de autor basada en el producto local elevado.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','lujo','Turismo de lujo','Municipio costero y residencial de baja densidad preferido por las grandes fortunas de la región que buscan la máxima privacidad frente al mar Cantábrico. Su infraestructura premium destaca por urbanizaciones cerradas e inteligentes como Liencres y Renedo, compuestas por mansiones vanguardistas blindadas en entornos naturales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','lujo','Turismo de lujo','Capital de la Ribeira Sacra lucense que funciona como el centro logístico y de servicios para el turismo premium de interior en el norte de Galicia. Su infraestructura cuenta con el emblemático Parador de Monforte, ubicado en el Monasterio de San Vicente del Pino, y pazos de gestión privada destinados al alquiler vacacional íntegro de alto standing con servicio de mayordomía. Dispone de helipuertos y embarcaderos privados en los cañones fluviales adyacentes, ofreciendo rutas exclusivas en catamarán de lujo y catas privadas de vinos de viticultura heroica orientadas a coleccionistas globales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','lujo','Turismo de lujo','Municipio de interior posicionado en el mercado residencial de alta gama internacional gracias al mega-complejo privado Condado de Alhama. Esta infraestructura de estilo de vida premium cuenta con un campo de golf de campeonato de 18 hoyos diseñado personalmente por Jack Nicklaus, caracterizado por sus estrictos perímetros de seguridad y control de acceso. El resort alberga villas inteligentes de diseño contemporáneo, spas médicos y centros deportivos de alto rendimiento. Ofrece servicios de conserjería personalizada y helipuertos civiles autorizados para transfers directos desde los aeropuertos de la región.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','lujo','Turismo de lujo','Histórica villa amurallada en la frontera francesa, consolidada como uno de los destinos residenciales y de veraneo más exclusivos del Norte de España. Su infraestructura premium destaca por el Club Náutico de Hondarribia, una marina de gran calado que acoge yates de alta eslora y ofrece chárters VIP para navegar por el Cantábrico. El barrio residencial de Jaizkibel alberga mansiones multimillonarias rodeadas de un entorno blindado. Su oferta gastronómica es de primer nivel mundial, combinando asadores de élite con alta cocina galardonada con Estrellas Michelin (como el restaurante Alameda).','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','lujo','Turismo de lujo','Villa medieval de la provincia de Toledo que esconde un potente reducto de turismo premium enfocado en la privacidad absoluta. Su fisonomía urbana está presidida por el Castillo de Oropesa (hoy Parador de Oropesa), el primer parador nacional ubicado en un edificio histórico. Su entorno rústico destaca por inmensas dehesas y fincas fortificadas de miles de hectáreas orientadas a la caza mayor y la hípica de alta competición. Estas propiedades, pertenecientes a la aristocracia y grandes empresarios madrileños, cuentan con helipuertos privados autorizados y pabellones de ultra-lujo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','lujo','Turismo de lujo','Municipio de interior consolidado como un nodo estratégico para el enoturismo premium y el turismo residencial discreto en la provincia de Alicante. Su infraestructura de alta gama destaca por bodegas boutique de producción limitada ubicadas en fincas históricas, las cuales ofrecen salas de catas privadas subterráneas y experiencias personalizadas para grandes inversores internacionales. Cuenta con el Econaturismo de Ultra-Lujo en antiguas alquerías rehabilitadas con presupuestos millonarios y pistas de aterrizaje privadas autorizadas para aeronaves ligeras, atrayendo a empresarios europeos que buscan un aislamiento absoluto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','lujo','Turismo de lujo','Histórica sede de la corte de los Reyes de Navarra que ha desarrollado un sólido nicho de turismo premium cultural y enológico de alta gama. Su fisonomía está presidida por el imponente Palacio Real de Olite, que alberga en su conjunto monumental el Parador de Olite. Su infraestructura exclusiva se cimienta en bodegas centenarias amparadas bajo la D.O. Navarra, las cuales disponen de comedores privados y santuarios de barricas accesibles solo bajo invitación VIP. El municipio ofrece un entorno de máxima seguridad, festivales culturales con zonas VIP exclusivas y restaurantes gourmet de alta cocina foral.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','lujo','Turismo de lujo','La capital logística y de servicios de la Costa da Morte que ha desarrollado un sector residencial e inmobiliario de alto standing integrado en la naturaleza cantábrica. Su infraestructura premium prescinde del gigantismo y se enfoca en antiguas casonas de piedra y palacetes de indianos rehabilitados como hoteles boutique de alta gama que garantizan el anonimato absoluto. Dispone de un puerto natural idóneo para el fondeo discreto de embarcaciones de recreo de eslora media-alta y ofrece una selecta red de gastronomía gourmet especializada en marisco de lonja de máxima pureza.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','lujo','Turismo de lujo','Histórico baluarte ducal en el corazón de la comarca de La Janda, preferido por la aristocracia andaluza y empresarios internacionales en busca de máxima privacidad. Su infraestructura de ultra-lujo se asienta en la reconversión de espectaculares casas palacio barrocas en hoteles boutique de alta gama dotados de servicios de conserjería personalizados. Su entorno rústico destaca por albergar dehesas privadas y fincas fortificadas de miles de hectáreas destinadas a la cría de caballos de pura raza española y reses bravas, equipadas con helipuertos autorizados y pabellones residenciales VIP cerrados al público general.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30036','lujo','Turismo de lujo','Destino estratégico posicionado en el turismo de salud, bienestar y náutica premium dentro del Mar Menor. Su infraestructura de alta gama destaca por el puerto deportivo Marina de las Salinas, que ofrece amarres de gran calado para yates deportivos, servicios de chárter VIP y restauración gourmet en primera línea. El municipio alberga hoteles de 5 estrellas especializados en talasoterapia y tratamientos médicos exclusivos con los lodos naturales de la zona. Sus colinas residenciales cuentan con búnkeres inmobiliarios de villas inteligentes con seguridad perimetral avanzada y total privacidad.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','lujo','Turismo de lujo','Histórica ciudad medieval que ha desarrollado un potente nicho de turismo premium gracias al complejo internacional MotorLand Aragón. Esta infraestructura del motor atrae a pilotos, escuderías de élite y magnates internacionales, ofreciendo zonas VIP exclusivas, helipuertos operativos y salas privadas de alto standing. Su planta hotelera destaca por el Parador de Alcañiz, ubicado en un espectacular castillo-palacio del siglo XII. Su entorno rural esconde masías fortificadas de alquiler íntegro con la máxima discreción y seguridad para perfiles corporativos globales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','lujo','Turismo de lujo','Exclusivo bastión residencial situado en la periferia de la capital de la isla, preferido históricamente por la alta burguesía y el cuerpo diplomático internacional. Su fisonomía destaca por impresionantes mansiones de arquitectura colonial inglesa y chalets inteligentes blindados de alta seguridad. Cuenta con acceso inmediato al Real Club de Golf de Las Palmas y a prestigiosos centros ecuestres privados. El municipio ofrece un entorno de clima templado durante todo el año, clínicas de medicina estética personalizada y restaurantes de alta cocina atlántica de vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','lujo','Turismo de lujo','La capital del Valle de los Pedroches funciona como un destino de ultra-lujo discreto especializado en el sector agroalimentario premium y el turismo de dehesa de alto standing. Carece de grandes infraestructuras hoteleras masivas, pero su puntuación radica en sus extensas fincas privadas y dehesas de encinas milenarias, donde se produce el jamón ibérico de bellota de máxima pureza (D.O.P. Los Pedroches). Estas propiedades cuentan con cortijos señoriales reformados con presupuestos millonarios de uso exclusivo, helipuertos autorizados y estrictos perímetros de seguridad.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11014','lujo','Turismo de lujo','La capital histórica del Maestrazgo castellonense funciona como un refugio de "lujo silencioso" y total anonimato para empresarios que huyen de la sobreexposición mediática. Su infraestructura premium prescinde del formato de cadenas masivas. Se apoya en la reconversión de antiguos palacios góticos y casonas de piedra en alojamientos boutique de alta gama de alquiler íntegro con tarifas premium. El municipio ofrece un entorno de alta seguridad geográfica, helipuertos privados autorizados en fincas agrícolas de olivos milenarios y servicios personalizados de chefs privados que reinterpretan la cocina tradicional de interior con trufa negra local.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','lujo','Turismo de lujo','El baluarte del enoturismo premium en el extremo oriental de la D.O. Ribera del Duero. Su infraestructura exclusiva se cimienta en bodegas de producción limitada que elaboran vinos de cepas viejas y cultivo tradicional altamente cotizados en mercados internacionales. Estas propiedades cuentan con salas de catas privadas subterráneas excavadas en la roca y zonas de aterrizaje para helicópteros destinadas a inversores y coleccionistas globales. El municipio ofrece un entorno medieval protegido, alojamientos boutique integrados en la.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','lujo','Turismo de lujo','Situado en el centro geográfico de la isla, combina su prestigio como cuna histórica del diseño de calzado y marroquinería de alta gama con un floreciente sector residencial rural premium. Alberga los talleres artesanales y sedes de firmas de lujo con proyección internacional, las cuales disponen de salas VIP de atención personalizada para clientes de alto standing. Su entorno rústico cuenta con una densa infraestructura de agroturismos de 5 estrellas y fincas señoriales fortificadas que garantizan un anonimato absoluto, respaldadas por cellers tradicionales reconvertidos en restaurantes de alta cocina mediterránea de vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41079','lujo','Turismo de lujo','Municipio estratégico situado en el linde de las marismas del Guadalquivir, consolidado como un destino de ultra-lujo discreto especializado en el sector hípico de alta competición y el recreo señorial de la aristocracia andaluza. Su infraestructura premium destaca por históricas haciendas y extensiones de dehesa fortificadas, propiedad de terratenientes y empresarios internacionales. Estas fincas están equipadas con helipuertos privados, embarcaderos exclusivos en el río navegable para yates de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90057','lujo','Turismo de lujo','Nota de enfoque conjunto: Estos dos municipios vecinos de la costa vizcaína constituyen uno de los refugios residenciales marítimos más exclusivos y cotizados del Norte de España [Image 1]. Su infraestructura premium destaca por las urbanizaciones fortificadas e inteligentes situadas en las colinas forestales que miran a la bahía, donde grandes empresarios de Bilbao poseen.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','lujo','Turismo de lujo','El término municipal más extenso de la región esconde un potente reducto de ultra-lujo y total opacidad en el corazón del Valle de Alcudia. Carece por completo de infraestructura urbana masiva, pero su altísima puntuación radica en albergar masivas fincas de caza mayor y dehesas fortificadas de miles de hectáreas, propiedad de magnates mundiales, fondos internacionales y miembros de familias reales europeas. Estas propiedades privadas de súper-lujo cuentan con helipuertos civiles homologados, seguridad perimetral de nivel militar con guardería propia, pabellones residenciales con servicios de chef privado de alto standing y experiencias ecuestres exclusivas inaccesibles para el público general.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01052','lujo','Turismo de lujo','Pequeño municipio de la Rioja Alavesa que compite directamente en la cúspide del turismo de lujo internacional. Su infraestructura se apoya de forma.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','lujo','Turismo de lujo','Ciudad histórica que funciona como un potente polo de atracción para el turismo premium cultural, deportivo y residencial de interior en la Costa del Sol interior. Su fisonomía urbana cuenta con palacios señoriales y una planta hotelera boutique de alta gama de 5 estrellas que garantiza la máxima privacidad a personalidades mundiales. Su infraestructura exclusiva destaca por albergar el circuito privado de automovilismo Ascari Resort, un búnker del motor de ultra-lujo con helipuerto, club social exclusivo y pistas de carreras para dueños de superdeportivos internacionales. Su entorno rústico cuenta además con espectaculares bodegas de autor con catas privadas y cortijos fortificados de uso exclusivo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','lujo','Turismo de lujo','La capital histórica de la cultura sidrera vasca ha sofisticado su oferta para captar al turismo gastronómico internacional de alto poder adquisitivo. Su infraestructura premium destaca por la reconversión de caseríos centenarios en templos culinarios experimentales que ofrecen catas privadas de ediciones limitadas y menús maridados diseñados por chefs de renombre. En su vertiente inmobiliaria, el municipio alberga urbanizaciones residenciales cerradas de baja densidad con chalets inteligentes y avanzados sistemas de seguridad privada, elegidos por directivos e investigadores de la cercana San Sebastián que buscan máxima discreción y anonimato.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41040','lujo','Turismo de lujo','Ubicado en la comarca del Aljarafe, es uno de los bastiones residenciales e hípicos más tradicionales de la provincia de Sevilla. Su infraestructura de lujo destaca por exclusivas urbanizaciones cerradas con patrullas de seguridad 24/7, donde se erigen mansiones contemporáneas de gran envergadura. Su entorno rústico alberga históricas haciendas de olivar y fincas palaciegas privadas equipadas con helipuertos homologados, instalaciones ecuestres de nivel profesional y picaderos olímpicos orientados a la cría de caballos de pura raza española, sirviendo de refugio para la aristocracia y grandes empresarios de la capital.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90016','lujo','Turismo de lujo','El máximo exponente del concepto "barefoot luxury" y el aislamiento absoluto en el interior de Menorca. Su infraestructura premium prescinde por completo de los desarrollos hoteleros masivos y se concentra en fincas rústicas milenarias y antiguos "llocs" transformados en agroturismos de 5 estrellas Gran Lujo, como el exclusivo Menorca Experimental. El término municipal está dominado por mansiones campestres fortificadas y de alquiler vacacional ultra-privado que cuentan con helipuertos ocultos entre la vegetación mediterránea, ofreciendo servicios de conserjería VIP, chefs privados y accesos restringidos a zonas costeras vírgenes e idóneas para el fondeo discreto de yates de gran eslora.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','lujo','Turismo de lujo','Histórico municipio tinerfeño que se extiende desde las laderas del Teide hasta el océano, consolidado como un destino premium para el turismo cultural, residencial y de naturaleza. El casco antiguo destaca por sus espectaculares casas señoriales de arquitectura tradicional canaria y palacetes del siglo XVII, muchos de ellos rehabilitados como museos privados, salas de catas exclusivas o alojamientos boutique de alta gama. En sus zonas de medianías y fincas agrícolas protegidas se ocultan villas de ultra-lujo y eco-resorts privados que garantizan total anonimato a celebridades internacionales, complementados con servicios de helitransporte y una gastronomía tradicional elevada a la alta cocina de autor.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','lujo','Turismo de lujo','Uno de los municipios con mayor renta per cápita y seguridad de España. Su infraestructura premium destaca por urbanizaciones ultraprivadas e hiper-vigiladas como Las Lomas, Bonanza o Valdecabañas, caracterizadas por mansiones inteligentes de diseño vanguardista. Alberga el exclusivo Club de Golf Las Encinas y prestigiosos centros ecuestres y de tenis privados. El municipio cuenta con sedes de centros médicos privados de alta gama, centros de bienestar de lujo y una selecta oferta comercial y de restauración gourmet orientada a empresarios de alto standing, directivos y futbolistas de élite que exigen una privacidad total.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','lujo','Turismo de lujo','Histórico y aristocrático destino de veraneo e invierno de la alta burguesía barcelonesa en el Pirineo de Girona. Su infraestructura residencial premium destaca por las majestuosas mansiones y chalets de principios del siglo XX en el Paseo Maristany, una de las avenidas más cotizadas y exclusivas de la región. El municipio ofrece un entorno de máxima discreción y seguridad, contando con hoteles boutique de alta gama, el centenario Club de Golf Camprodon y una selecta gastronomía de alta montaña que reinterpreta el recetario tradicional catalán con producto km 0 de la máxima calidad.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12082','lujo','Turismo de lujo','Nota de enfoque premium: Lejos del circuito turístico masivo, este litoral ha desarrollado un sector inmobiliario residencial de alto standing y baja densidad sumamente cotizado. Su infraestructura destaca por exclusivas promociones de villas inteligentes de diseño contemporáneo en primera línea de playa con sistemas de seguridad avanzados. El municipio ofrece servicios de conserjería personalizados para residentes internacionales de alto poder adquisitivo y se beneficia de su cercanía logística a marinas premium de la provincia para el chárter y amarre de embarcaciones de recreo de media y gran eslora.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','lujo','Turismo de lujo','El epicentro internacional de la cultura del atún rojo de almadraba y el "lujo descalzo" en la Costa de la Luz. Su infraestructura de alta gama destaca por la urbanización hiper-exclusiva Atlanterra, un búnker inmobiliario colgado sobre los acantilados donde grandes fortunas internacionales poseen mansiones de diseño vanguardista con helipuertos privados ocultos. Cuenta con hoteles boutique de 5 estrellas orientados al bienestar físico y mental, clubes de playa de alto standing y un ecosistema culinario de primer nivel mundial liderado por restaurantes icónicos de alta cocina (como El Campero), atrayendo a sibaritas de todo el planeta.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','lujo','Turismo de lujo','Esta villa medieval amurallada funciona como uno de los refugios de desconexión más exclusivos para la élite financiera e intelectual de Madrid. Su infraestructura premium se basa en la estricta conservación de su patrimonio, con antiguos palacios y casonas de piedra del siglo XVI rehabilitados como hoteles boutique de alta gama o residencias de alquiler íntegro con tarifas premium. El municipio garantiza un anonimato absoluto gracias a su acceso restringido de vehículos, y su oferta se complementa con helipuertos privados en las fincas colindantes, asadores.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43069','lujo','Turismo de lujo','El verdadero sanctasanctórum del vino de alta gama en la D.O.Q. Priorat. Su infraestructura está dominada por bodegas de renombre mundial (como Alvaro Palacios o Clos i Terrasses) que elaboran algunos de los vinos más caros y codiciados por coleccionistas de todo el planeta. Estas instalaciones cuentan con santuarios de barricas privados, helipuertos operativos en sus fincas para el traslado directo de grandes inversores internacionales y salas de catas exclusivas de acceso restringido. La planta hotelera se compone de alojamientos boutique de diseño minimalista integrados en el paisaje de viñedos en terrazas, ofreciendo un entorno de máximo aislamiento y discreción.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46216','lujo','Turismo de lujo','Uno de los municipios con mayor renta per cápita de la Comunidad Valenciana, consolidado como el bastión residencial histórico de la alta burguesía, empresarios y diplomáticos de la capital del Turia. Su fisonomía urbana destaca por las impresionantes mansiones señoriales de principios del siglo XX de la zona de la Colonia de Rocafort y los chalets inteligentes de la urbanización privada Santa Bárbara. Este complejo blindado cuenta con avanzados.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','lujo','Turismo de lujo','Nota de enfoque premium: Más allá de su turismo urbano costero tradicional, el área protegida y los acantilados de la pedanía de Maro albergan un cotizado sector de turismo residencial y de "lujo descalzo". En sus laderas forestales se ocultan espectaculares villas de diseño contemporáneo e inteligente con piscinas infinitas que ofrecen una privacidad total y vistas panorámicas completas al mar de Alborán. El municipio ofrece servicios de chárter VIP de yates desde su caladero natural, experiencias de buceo premium personalizadas en sus parajes marítimos protegidos y una selecta restauración gourmet de cocina mediterránea de autor.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','lujo','Turismo de lujo','Conocido como el Valle de las Mil Palmeras, es el epicentro del "lujo silencioso" y la desconexión ecológica en el norte de Lanzarote. Su infraestructura premium destaca por una planta inmobiliaria basada en la rehabilitación de casonas coloniales canarias y villas eco-vanguardistas de baja densidad que garantizan la máxima privacidad a directivos e intelectuales internacionales. El municipio acoge la histórica Casa-Museo de César Manrique y ofrece una gastronomía km 0 hiper-refinada, además de un acceso privilegiado a los fondeaderos naturales del norte, idóneos para el descanso discreto de megayates privados.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','lujo','Turismo de lujo','Municipio costero jalonado por el impresionante paisaje geológico del Flysch, convertido en un cotizado reducto residencial para las grandes fortunas vascas. Su infraestructura premium destaca por su puerto deportivo, que ofrece amarres para yates de media y gran eslora, y por urbanizaciones privadas compuestas por chalets de diseño contemporáneo integrados en las laderas marítimas. Cuenta.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','lujo','Turismo de lujo','Histórica e industrial villa de la campiña sevillana que funciona como uno de los bastiones rurales más exclusivos de la aristocracia andaluza. Su infraestructura de súper-lujo se asienta en inmensas fincas rústicas y haciendas de olivar fortificadas, propiedad de grandes terratenientes y empresarios globales. Estas propiedades privadas cuentan con helipuertos homologados, pabellones de caza de alto standing y picaderos olímpicos dedicados en exclusiva a la cría y exportación de caballos de pura raza española, garantizando una privacidad total lejos del foco mediático.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28903','lujo','Turismo de lujo','Municipio tecnológico y residencial caracterizado por un urbanismo inteligente de alta seguridad y una de las rentas per cápita más estables de la región. Su infraestructura de gama alta destaca por urbanizaciones residenciales exentas de masificación, clínicas privadas de medicina estética y regenerativa, y clubes deportivos de alto standing. Su entorno natural inmediato ofrece acceso a exclusivos cotos de caza menor, rutas ecuestres.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','lujo','Turismo de lujo','Uno de los refugios veraniegos más codiciados por el alto patrimonio europeo en la Costa Brava. Su infraestructura premium destaca por búnkeres residenciales y urbanizaciones fortificadas como Sa Punta, Aiguablava y Sa Riera, repletas de mansiones vanguardistas suspendidas sobre acantilados marinos. Dispone del emblemático Hotel Aigua Blava y resorts boutique de 5.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','lujo','Turismo de lujo','Antigua capital del Reino de Asturias reconvertida en un nodo de turismo premium ecológico y de "lujo silencioso" a las puertas de los Picos de Europa. Su planta hotelera exclusiva cuenta con palacios históricos barrocos y casonas montañesas de piedra rehabilitadas como hoteles boutique de alta gama (como el.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','lujo','Turismo de lujo','Municipio estratégico en la vega del Guadalquivir, consolidado como un destino de ultra-lujo discreto especializado en el sector citrícola premium, la cría de caballos de pura raza española y el turismo residencial de interior. Su infraestructura de alta gama destaca por espectaculares haciendas andaluzas y palacios históricos reconvertidos en hoteles boutique señoriales, como el Monasterio de San Francisco. Sus extensas fincas privadas cuentan con estrictos perímetros de seguridad con guardería propia, helipuertos homologados y servicios de chef privado para la recepción de inversores agrícolas internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','lujo','Turismo de lujo','Municipio que esconde un reducto residencial de altísimo standing en la Cornisa Cantábrica, íntimamente ligado al entorno protegido del Parque Natural de Oyambre. Su infraestructura premium destaca por exclusivas fincas rústicas y casonas montañesas fortificadas propiedad de la aristocracia y grandes empresarios de Madrid, que buscan desconexión absoluta. El municipio ofrece acceso directo al histórico campo de golf de Oyambre (en su límite inmediato), playas vírgenes perfectas para el fondeo discreto de embarcaciones de recreo medianas, y selectas escuelas de surf con servicios VIP de entrenamiento personalizado para directivos corporativos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','lujo','Turismo de lujo','Nodo estratégico de la D.O. León que ha desarrollado una infraestructura premium centrada en el enoturismo de alta gama e inversiones internacionales. Su.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03033','lujo','Turismo de lujo','Municipio que alberga el mega-complejo de alto standing Ciudad Quesada, uno de los bastiones residenciales de lujo internacional más consolidados de la Costa Blanca Sur. Su infraestructura premium destaca por el campo de golf de 18 hoyos La Marquesa Golf, un prestigioso club privado rodeado por exclusivas urbanizaciones blindadas de villas inteligentes y chalets de diseño de vanguardia con seguridad perimetral avanzada 24/7. Cuenta con hoteles boutique de alta gama enfocados al bienestar, clínicas de cirugía y medicina estética privada, helipuertos y exclusivos servicios de conserjería para residentes extranjeros de alto poder adquisitivo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','lujo','Turismo de lujo','Histórica villa fortificada colgada de un imponente tajo rocoso, consolidada como el.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','lujo','Turismo de lujo','El bastión residencial de mayor estatus de la alta burguesía industrial asturiana. Su infraestructura premium destaca por urbanizaciones fortificadas de muy baja densidad y mansiones de arquitectura señorial con avanzados sistemas de seguridad perimetral. En sus lindes inmediatas alberga las exclusivas instalaciones del Real Club de Golf de Castiello y el prestigioso Complejo Deportivo Las Mestas, sede de concursos de saltos hípicos internacionales que atraen a la élite ecuestre europea. Su entorno ofrece clínicas de salud privada de alta gama, servicios de conserjería personalizados y una alta cocina asturiana gourmet de autor que aprovecha el mejor producto de la lonja del Musel.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47114','lujo','Turismo de lujo','Uno de los grandes nodos mundiales del enoturismo de ultra-lujo, presidido por su icónico castillo medieval que alberga el Museo Provincial del Vino. Su infraestructura exclusiva se cimienta en bodegas de renombre global (como Protos o Pago de Carraovejas) que cuentan con proyectos arquitectónicos de vanguardia, helipuertos operativos en sus fincas para el traslado directo de grandes inversores y coleccionistas VIP, y comedores privados hiperexclusivos. Su planta hotelera destaca por alojamientos boutique de 5 estrellas de diseño contemporáneo integrados entre viñedos históricos y una oferta culinaria de primer nivel mundial que fusiona el lechazo tradicional con técnicas de vanguardia culinaria.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25004','lujo','Turismo de lujo','La antigua capital de la isla funciona como un oasis de "lujo silencioso" y desconexión absoluta para altos directivos y empresarios que huyen por completo de la exposición mediática. Su infraestructura premium prescinde del formato de cadenas hoteleras masivas o zonas comerciales. Se apoya en la reconversión de espectaculares casonas señoriales y fincas rústicas de piedra volcánica en eco-resorts boutique de ultra-lujo de alquiler íntegro con tarifas premium. El municipio ofrece un entorno de máxima seguridad geográfica, helipuertos privados autorizados en propiedades particulares y experiencias personalizadas de astroturismo VIP bajo un cielo nocturno certificado internacionalmente por su pureza.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','lujo','Turismo de lujo','Histórica ciudad barroca y señorial de la campiña sevillana, célebre por sus espectaculares torres y palacios, que funciona como uno de los bastiones rurales más exclusivos de la aristocracia andaluza. Su infraestructura de súper-lujo se asienta en inmensas haciendas de olivar y fincas rústicas fortificadas de miles de hectáreas, propiedad de grandes terratenientes y empresarios globales. Estas propiedades privadas cuentan con helipuertos homologados, pabellones de caza de alto standing y picaderos olímpicos dedicados en exclusiva a la cría, doma y exportación de caballos de pura raza española, garantizando una privacidad total y servicios de chef privado de alto nivel bajo demanda.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','lujo','Turismo de lujo','Considerada la marina residencial más grande de Europa por su extensión de canales navegables. Su infraestructura premium destaca por una red de más de 23 kilómetros de canales interiores navegables que permiten a los propietarios de mansiones de alto standing amarrar sus yates directamente en la puerta de sus residencias privadas. El municipio cuenta con puertos deportivos especializados con amarres de gran calado, un aeródromo privado y centro de paracaidismo de renombre internacional con zonas VIP, helipuertos operativos y una.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','lujo','Turismo de lujo','Histórico y señorial pueblo de montaña que representa el máximo exponente del "lujo silencioso" y la exclusividad residencial en la Sierra de Tramuntana. Su fisonomía está marcada por la Real Cartuja y por exclusivas propiedades rurales rústicas (posesions) fortificadas de miles de metros cuadrados ocultas entre olivares milenarios, propiedad de grandes fortunas, actores y empresarios globales que exigen anonimato absoluto. Su infraestructura premium incluye agroturismos de 5 estrellas Gran Lujo, el exclusivo hotel boutique Mirabó de Valldemossa, helipuertos privados autorizados en propiedades particulares y una selecta gastronomía de alta cocina mallorquina.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','lujo','Turismo de lujo','Histórico Real Sitio y Paisaje Cultural Patrimonio de la Humanidad que ha desarrollado una infraestructura premium dirigida al turismo cultural, ecuestre y residencial de alto standing. Su fisonomía urbana destaca por el Palacio Real de Aranjuez y sus jardines monumentales. Cuenta con el prestigioso Club de Golf Cortijo Grande en sus inmediaciones y una planta inmobiliaria de fincas históricas y chalets residenciales de baja densidad dotados de avanzados sistemas de seguridad. Su gastronomía de ultra-lujo destaca.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','lujo','Turismo de lujo','Puerto pesquero estratégico que ha desarrollado un sólido segmento residencial e inmobiliario de alto standing enfocado al turismo náutico, ecológico y gastronómico de lujo. Su infraestructura premium cuenta con el Puerto Deportivo de Isla Cristina, una marina moderna equipada con amarres para embarcaciones recreativas de gran eslora y servicios de chárter VIP para navegar hacia el Algarve portugués. El municipio alberga exclusivas urbanizaciones integradas en parajes naturales protegidos, hoteles de alta gama especializados en turismo de bienestar y una alta restauración marina basada en el producto selecto de su lonja.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','lujo','Turismo de lujo','Histórica villa marinera reconvertida en uno de los destinos residenciales y de veraneo más exclusivos de la costa central cántabra [Ref]. Su infraestructura premium destaca por chalets de diseño de vanguardia construidos sobre los acantilados de la zona de La Concha y Los Locos, con total privacidad y vistas panorámicas. El municipio ofrece un puerto deportivo adaptado para veleros y yates de eslora media-alta, escuelas de surf de élite con instructores VIP personalizados y una selecta red gastronómica especializada en pescados de roca y mariscos salvajes del Cantábrico, atrayendo a directivos de la cornisa norte.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47129','lujo','Turismo de lujo','Municipio estratégico dentro de la "Milla de Oro" de la Ribera del Duero que alberga algunas de las bodegas más deseadas del mundo, como Vega Sicilia o Domino de Pingus. Su infraestructura de ultralujo destaca por proyectos vinícolas hiper-exclusivos que reciben a grandes fortunas e inversores globales de forma.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46903','lujo','Turismo de lujo','Uno de los principales enclaves residenciales premium de la periferia de Valencia Capital. Su infraestructura de alta gama destaca por la urbanización cerrada y fortificada Colinas de San Antonio, caracterizada por mansiones contemporáneas inteligentes con avanzados sistemas de seguridad perimetral y patrullas 24/7. El municipio se beneficia de su cercanía inmediata a prestigiosos clubes de golf privados (como el cercano Club de Golf Escorpión), centros hípicos de alto rendimiento y colegios internacionales de élite, sirviendo como búnker residencial para grandes empresarios industriales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41060','lujo','Turismo de lujo','Histórica villa señorial vinculada históricamente a los grandes linajes de la nobleza andaluza. Su infraestructura de súper-lujo se asienta en inmensas haciendas de olivar y dehesas fortificadas de miles de hectáreas que garantizan un anonimato absoluto a sus propietarios. Estas fincas rústicas privadas cuentan con helipuertos homologados, pabellones de caza de alto standing.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','lujo','Turismo de lujo','Histórica villa medieval fortificada, catalogada de forma recurrente entre los pueblos más bellos de España, que funciona como un cotizado nodo de turismo de "lujo silencioso" en el Pirineo aragonés. Su infraestructura de alta gama prescinde de las grandes cadenas hoteleras y se.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90891','lujo','Turismo de lujo','Municipio que conforma uno de los vértices más exclusivos del "Triángulo de Oro" del Ampurdán interior, el refugio predilecto de las grandes fortunas de Barcelona y del norte de Europa. Su infraestructura premium se integra de forma invisible en la naturaleza, basándose en la adquisición y restauración multimillonaria de masías fortificadas medievales con impresionantes sistemas de seguridad privada y total opacidad. La planta de alojamiento del municipio cuenta con exclusivos hoteles boutique de 5 estrellas de baja densidad arquitectónica, con amplias zonas de helipuerto privado, clubes hípicos de alto rendimiento y restaurantes culinarios de autor con menús degustación de alta cocina ampurdanesa de km 0.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35022','lujo','Turismo de lujo','Municipio que combina un espectacular entorno volcánico y palmerales en su cuenca interior con un consolidado desarrollo de turismo residencial de alto standing y baja densidad en las colinas que miran hacia la costa sur. Su infraestructura exclusiva destaca por villas inteligentes de diseño contemporáneo y antiguas haciendas rurales rehabilitadas que garantizan la máxima privacidad a directivos e intelectuales internacionales que exigen un anonimato total. Ofrece una selecta gastronomía gourmet basada en la pureza de los productos atlánticos y aceites locales premiados, y se beneficia de un acceso privilegiado a los servicios náuticos VIP y campos de golf de los municipios costeros colindantes.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','lujo','Turismo de lujo','Considerada la cuna histórica del cultivo del olivar premium y una de las capitales mundiales en la producción de aceites de oliva virgen extra de edición limitada. Su infraestructura de alta gama se cimienta en imponentes haciendas y fincas de olivar centenarias, propiedad de terratenientes y empresarios del sector agroalimentario internacional, muchas de las cuales han sido reformadas con presupuestos millonarios como alojamientos de ultra-lujo y alquiler íntegro privado. El municipio ofrece un entorno de baja exposición mediática, disponiendo de zonas autorizadas de helipuerto para la recepción de inversores extranjeros y catas privadas dirigidas en almazaras de diseño arquitectónico de vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47179','lujo','Turismo de lujo','Uno de los grandes templos de la "Milla de Oro" de la Ribera del Duero, internacionalmente codiciado por coleccionistas e inversores mundiales del vino. Su infraestructura exclusiva está capitaneada por el hotel de 5 estrellas Gran Lujo Castilla Termal Monasterio de Valbuena, un antiguo monasterio cisterciense del siglo XII reconvertido en un spa termal médico y de bienestar de nivel mundial. El municipio acoge viñedos míticos de la zona e instalaciones de bodegas premium que disponen de sus propios helipuertos homologados, comedores estrictamente privados para corporaciones globales y santuarios de barricas históricas con acceso exclusivo bajo invitación VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90769','lujo','Turismo de lujo','Nota de enfoque geográfico: Esta pedanía de interior se ha consolidado como el centro neurálgico del estilo de vida "boho-chic premium" en las Baleares. Su infraestructura de súper-lujo destaca por un mercado inmobiliario de fincas rústicas milenarias totalmente blindadas y rediseñadas por arquitectos de renombre internacional, que se alquilan de forma íntegra por tarifas de ultra-lujo a directivos y celebridades de todo el mundo. El casco urbano cuenta con sofisticadas galerías de arte, concept stores de moda internacional premium y una densa y exquisita oferta gastronómica internacional que opera bajo estrictos parámetros de privacidad para sus clientes VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03037','lujo','Turismo de lujo','Destino costero hiper-exclusivo que ha desarrollado un modelo de turismo residencial de baja densidad y altísimo standing, protegido de la masificación. Su infraestructura premium destaca por búnkeres inmobiliarios y mansiones de diseño contemporáneo vanguardista con piscinas infinitas que se cuelgan sobre los acantilados de las urbanizaciones Cap Blanc y Pla del Mar. Cuenta con el Club Náutico Moraira, una marina muy cotizada que ofrece amarres privados para yates deportivos, servicios de chárter VIP y una selecta red de alta restauración marinera con espectaculares vistas al peñón de Ifach.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','lujo','Turismo de lujo','El gran búnker rústico de la Sierra Morena cordobesa, consolidado como un destino de ultra-lujo discreto especializado en el turismo cinegético y agroalimentario internacional de alta gama. Carece de grandes cadenas hoteleras o zonas comerciales, pero su elevada puntuación radica en sus masivas fincas de caza mayor y dehesas fortificadas de miles de hectáreas, propiedad de la aristocracia europea y magnates globales. Estas propiedades cuentan con helipuertos privados autorizados, pabellones de caza de alto standing con sistemas de seguridad militarizada y servicios de chefs con Estrella Michelin que se desplazan en exclusiva para eventos corporativos restringidos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','lujo','Turismo de lujo','Municipio que concentra un sector inmobiliario residencial de alto standing y baja densidad en torno a la ría de Villaviciosa. Su infraestructura premium destaca por espectaculares casonas de indianos rehabilitadas y chalets inteligentes de diseño vanguardista colgados sobre los acantilados marinos que miran al Cantábrico. Se beneficia de servicios de amarre para veleros y yates medianos en su caladero natural y ofrece una cotizada gastronomía marina en el pintoresco núcleo de Tazones, especializada en marisco salvaje de máxima pureza que atrae a perfiles corporativos y sibaritas internacionales que exigen un anonimato total.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','lujo','Turismo de lujo','Municipio fronterizo integrado en el extremo occidental de la D.O. Ribera del Duero que funciona como un destino oculto de "lujo silencioso". Su infraestructura premium se basa en la baja densidad residencial y en bodegas artesanales de producción muy limitada que producen vinos de cepas viejas cotizados por grandes coleccionistas mundiales. Ofrece salas de catas privadas subterráneas de acceso restringido y zonas autorizadas de aterrizaje de helicópteros en fincas particulares. Los alojamientos se componen de casonas de piedra medievales rehabilitadas como hoteles boutique de alta gama que aseguran un anonimato total a empresarios de la capital.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','lujo','Turismo de lujo','Consolidado como la gran extensión del lujo costero internacional de la Costa del Sol. Su infraestructura de alta gama destaca por la conocida "Nueva Milla de Oro", un eje litoral que alberga resorts de 5 estrellas Gran Lujo como el Kempinski Hotel Bahía, el vanguardista IKOS Andalusía o el exclusivo club residencial The Edge. Cuenta con puertos deportivos perfectamente equipados para el amarre de yates recreativos y veleros de alta eslora, centros ecuestres de nivel olímpico (Escuela de Arte Ecuestre Costa del Sol), campos de golf de prestigio internacional y lujosos clubes de playa frente al mar que atraen a fortunas globales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90854','lujo','Turismo de lujo','Municipio de interior costero posicionado sólidamente en el turismo residencial internacional premium gracias al prestigioso complejo cerrado La Finca Resort. Esta infraestructura estrella cuenta con un campo de golf de campeonato de 18 hoyos de primer nivel, un hotel de 5 estrellas enfocado al bienestar, un spa de alta gama, centros de entrenamiento de alto rendimiento y restaurantes de cocina de autor. El resort está rodeado por exclusivas promociones de villas inteligentes y chalets de diseño de vanguardia dotados de seguridad privada perimetral avanzada y total privacidad para sus residentes VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','lujo','Turismo de lujo','Municipio que concentra, junto a Puigcerdà, el turismo invernal y de montaña de mayor estatus del Pirineo Oriental. Su infraestructura premium destaca por urbanizaciones residenciales integradas de chalets de madera noble y piedra con máxima seguridad privada en la zona de Super Molina. Dispone de pistas con zonas VIP exclusivas, escuelas de esquí con monitores personales para perfiles de alto standing, helipuertos operativos para conexiones rápidas con Barcelona y el hotel de alta gama Hotel Sercotel Alp Masella. Su gastronomía de montaña de autor se complementa con refinados clubes privados de "après-ski".','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47104','lujo','Turismo de lujo','Histórica villa de los Siete Linajes que ha desarrollado una infraestructura premium centrada en el turismo de salud, bienestar y enoturismo selecto. Su gran pilar es el hotel de 4 y 5 estrellas Castilla Termal Balneario de Olmedo, ubicado en un antiguo convento del siglo XII sobre un manantial de aguas mineromedicinales, dotado de spas médicos de alta gama. El municipio ofrece un entorno de máxima discreción, fincas señoriales de alquiler vacacional exclusivo, helipuertos privados autorizados para transfers ejecutivos y restaurantes de alta cocina castellana de vanguardia.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41093','lujo','Turismo de lujo','El municipio con la mayor renta per cápita de toda Andalucía y el gran bastión residencial premium de la periferia inmediata de Sevilla Capital. Su infraestructura de súper-lujo destaca por urbanizaciones fortificadas de baja densidad como Santa Eufemia o Zaudín, esta última organizada en torno al exclusivo Club de Golf Zaudín (diseñado por Gary Player, con estrictos derechos de admisión). Cuenta con chalets inteligentes de diseño arquitectónico contemporáneo, avanzados sistemas de seguridad privada, clínicas médico-estéticas personalizadas y centros de negocios VIP con helipuertos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','lujo','Turismo de lujo','Considerado el portal de acceso a la Costa Brava para el alto patrimonio. Su infraestructura premium se desmarca de la zona urbana masiva y se concentra en la urbanización privada Cala Sant Francesc y el enclave de Santa Cristina. Destaca por mansiones inteligentes de diseño contemporáneo encajadas en acantilados con estrictos sistemas de vigilancia 24/7. El municipio dispone del Club de Vela Blanes, una marina moderna equipada con amarres de gran calado, y ofrece una selecta restauración mediterránea gourmet km 0 con acceso restringido, ideal para el descanso de empresarios corporativos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','lujo','Turismo de lujo','Villa histórica declarada Conjunto Histórico-Artístico que funciona como un potente polo de atracción para el enoturismo de ultra-lujo en la Ribera del Duero. Su infraestructura exclusiva se cimienta en bodegas de renombre global como Bodegas Portia, cuyo edificio de vanguardia fue diseñado por el célebre arquitecto Norman Foster. Estas instalaciones cuentan con helipuertos operativos para el traslado de inversores internacionales, comedores estrictamente privados para corporaciones globales y santuarios de barricas históricas con acceso exclusivo bajo invitación VIP.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50089','lujo','Turismo de lujo','El municipio con el mayor crecimiento de renta per cápita y perfil joven-ejecutivo de la provincia de Zaragoza. Su infraestructura premium destaca por urbanizaciones cerradas de baja densidad compuestas por chalets inteligentes de diseño minimalista con avanzados sistemas de seguridad privada y patrullas constantes. El municipio se beneficia de su cercanía inmediata a prestigiosos clubes de tenis y equitación privados de la periferia zaragozana, centros de medicina estética personalizada y una selecta restauración corporativa VIP enfocada al sector empresarial multinacional.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','lujo','Turismo de lujo','Histórica e industrial villa ducal de la campiña sevillana, célebre por albergar la calle con la arquitectura barroca más pura de Europa según la UNESCO. Su infraestructura de súper-lujo se asienta en inmensas haciendas de olivar y fincas rústicas fortificadas de miles de hectáreas, propiedad de grandes terratenientes y aristócratas. Estas propiedades privadas cuentan con helipuertos homologados, pabellones de caza de alto standing y picaderos profesionales dedicados en exclusiva a la cría, doma y exportación de caballos de pura raza española, garantizando una privacidad total.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','lujo','Turismo de lujo','Distrito marítimo histórico que ha desarrollado un sector inmobiliario residencial de alto standing en sus laderas orientadas al mar Cantábrico. Su infraestructura premium destaca por chalets de diseño contemporáneo que garantizan la máxima privacidad en las colinas de Pasai Donibane. El puerto histórico ofrece muelles específicos para el atraque de embarcaciones exclusivas de eslora media-alta y servicios de chárter náutico VIP. Su oferta gastronómica se ha sofisticado con una selecta red de alta restauración marinera especializada en marisco salvaje de lonja, atrayendo a directivos de la comarca de San Sebastián.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49129','lujo','Turismo de lujo','Municipio estratégico integrado en el corazón de la D.O. Toro que funciona como un potente nodo de inversiones internacionales y enoturismo premium. Su infraestructura exclusiva se cimienta en bodegas de producción limitada que elaboran vinos tintos de cepas viejas prefiloxéricas altamente cotizados en subastas internacionales. Estas instalaciones cuentan con salas de catas privadas subterráneas y zonas de aterrizaje para helicópteros destinadas a inversores globales. El municipio ofrece alojamientos boutique de baja densidad integrados en el paisaje agrario y una alta restauración de caza.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','lujo','Turismo de lujo','Nota de enfoque residencial: Lejos del tejido industrial del municipio, los núcleos residenciales de La Canyada y Mas Camarena constituyen dos búnkeres de alta seguridad para la élite empresarial valenciana. Su infraestructura premium destaca por mansiones señoriales e inteligentes ocultas en parcelas boscosas hiper-vigiladas con patrullas 24/7. El entorno se organiza en torno a prestigiosos colegios internacionales, prestigiosos centros ecuestres y clubes de tenis privados con derechos de admisión restrictivos, sirviendo como refugio preferido para directivos e inversores.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','lujo','Turismo de lujo','Nota de enfoque geográfico: Alejado de la masificación urbana de su centro, la urbanización privada Roche constituye uno de los búnkeres inmobiliarios costeros más exclusivos de España. Su infraestructura de súper-lujo destaca por un trazado de mansiones inteligentes de diseño contemporáneo inmersas en un pinar protegido y protegidas con avanzados sistemas de seguridad perimetral. Cuenta con un exclusivo club de campo privado con pistas de tenis de alta competición, restaurantes gourmet especializados en atún rojo de almadraba y un litoral con calas protegidas idóneas para el fondeo discreto de yates.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','lujo','Turismo de lujo','Histórica villa señorial declarada Conjunto Histórico-Artístico que funciona como un destino oculto de ultra-lujo rústico y total anonimato. Su infraestructura exclusiva se cimienta en la reconversión de antiguas casonas de piedra y palacetes en hoteles boutique de alta gama, y en su cercanía al balneario histórico de Ledesma con aguas mineromedicinales. Su entorno rural está dominado por dehesas fortificadas de miles de hectáreas orientadas a la ganadería de reses bravas y al turismo ecuestre premium, equipadas con helipuertos privados autorizados para la recepción de empresarios de la capital.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30902','lujo','Turismo de lujo','Municipio costero posicionado sólidamente en el turismo residencial internacional premium gracias al complejo cerrado La Serena Golf y resorts náuticos de alto standing. Su infraestructura exclusiva cuenta con un campo de 18 hoyos diseñado por Manuel Piñero, un club social premium con restaurantes de alta cocina mediterránea y zonas de spa de alta gama. El municipio dispone del puerto deportivo Club Náutico Mar Menor, adaptado para el amarre de embarcaciones recreativas de media y gran eslora, y un denso parque inmobiliario de villas inteligentes con seguridad perimetral avanzada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','lujo','Turismo de lujo','Nota de enfoque geográfico: Alejado de las infraestructuras logísticas, la zona residencial costera de Mazagón (compartida con Moguer) alberga un cotizado búnker inmobiliario de baja densidad integrado en un entorno de dunas y pinares protegidos. Su infraestructura premium destaca por el Puerto Deportivo de Mazarrón en sus inmediaciones y por hoteles de alta gama enfocados al bienestar y la relajación total, como el Parador de Mazagón, situado sobre un acantilado con vistas directas al Atlántico. Ofrece un entorno de máxima discreción, playas vírgenes perfectas para el fondeo discreto de yates y una.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','lujo','Turismo de lujo','Histórica villa veraniega de la costa oriental que destaca por albergar un cotizado sector de turismo residencial de alto standing y baja densidad arquitectónica. Su infraestructura premium se desmarca del turismo de masas y se concentra en casonas señoriales montañesas y chalets contemporáneos inteligentes con avanzados sistemas de seguridad privada, ocultos cerca de las playas de Trengandín.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','lujo','Turismo de lujo','Municipio estratégico integrado en el linde oriental de la D.O.Ca. Rioja que funciona como un potente nodo de inversiones internacionales y enoturismo premium. Su infraestructura exclusiva se cimienta en bodegas de renombre global (como Palacios Remondo) que elaboran vinos de alta gama muy cotizados por coleccionistas de todo el planeta. Estas instalaciones cuentan con helipuertos operativos en sus fincas para el traslado directo de inversores internacionales, comedores estrictamente privados para corporaciones globales y salas de catas exclusivas en entornos rurales que aseguran un anonimato total.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38035','lujo','Turismo de lujo','Municipio sureño posicionado sólidamente en el mercado internacional premium gracias al gran eje de Golf del Sur y Amarilla Golf. Su infraestructura de ultra-lujo destaca por dos campos de golf de nivel de campeonato que lindan directamente con el océano Atlántico y la marina Marina San Miguel, un puerto deportivo de gran calado adaptado para el amarre de yates de gran eslora y.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90950','lujo','Turismo de lujo','Uno de los municipios más antiguos de Vizcaya, convertido hoy en un búnker de alta gama inmobiliaria. Su infraestructura se compone de exclusivas urbanizaciones de chalets de diseño contemporáneo e inteligente con piscinas infinitas colgadas sobre acantilados marinos de pendientes extremas. El municipio garantiza un anonimato total a directivos, empresarios y deportistas de élite que huyen de la exposición mediática, beneficiándose de su conectividad logística rápida con el área metropolitana de Bilbao y de escuelas de surf con servicios de entrenamiento VIP personalizado.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47158','lujo','Turismo de lujo','El verdadero corazón geográfico y de producción de la D.O. Rueda. Su infraestructura exclusiva se basa en bodegas boutique de producción ultra-limitada y fincas históricas que elaboran vinos blancos de cepas viejas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46135','lujo','Turismo de lujo','El núcleo señorial e inmobiliario por excelencia de la periferia inmediata de Valencia Capital. Su infraestructura premium destaca por la histórica urbanización privada Campolivar, un búnker cerrado con estrictos controles de acceso, patrullas de seguridad 24/7 y cámaras térmicas de videovigilancia. En este complejo residencial se erigen mansiones de escala masiva y palacetes de principios del siglo XX ocultos en parcelas de densa vegetación mediterránea, complementados con prestigiosos colegios británicos, clínicas médico-estéticas privadas y selectas terrazas gourmet.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17199','lujo','Turismo de lujo','Municipio que combina un imponente patrimonio monumental interior con el desarrollo náutico premium de su costa, vertebrado por el Club Nàutic Estartit. Esta moderna marina ofrece amarres de gran calado para yates deportivos, servicios de chárter VIP y centros de buceo premium con instructores personalizados para perfiles VIP orientados a explorar la reserva natural protegida de las Islas Medas. En sus colinas residenciales se erigen villas inteligentes de diseño contemporáneo que garantizan la privacidad perimetral avanzada y el anonimato absoluto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30021','lujo','Turismo de lujo','Municipio de interior costero posicionado sólidamente en el mercado residencial de alta gama internacional gracias al prestigioso complejo cerrado Hacienda del Álamo Golf Resort. Esta infraestructura estrella cuenta con un campo de golf de campeonato de 18 hoyos diseñado por el célebre Dave Thomas, un exclusivo club social premium con restaurantes de alta cocina, pistas de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07056','lujo','Turismo de lujo','Ubicado en la comarca del Raiguer, a los pies de la Sierra de Tramuntana, es el destino predilecto de fortunas centroeuropeas que buscan el concepto de "lujo rural señorial" con máxima discreción. Su infraestructura premium destaca por históricas fincas rústicas mallorquinas (posesions) y mansiones de piedra totalmente blindadas y rediseñadas por arquitectos de renombre internacional. El municipio cuenta con exclusivas bodegas boutique que ofrecen catas privadas subterráneas para coleccionistas, selectos mercadillos orgánicos gourmet y agroturismos de 5 estrellas Gran Lujo.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','lujo','Turismo de lujo','Antigua capital de provincia que ha desarrollado una infraestructura premium centrada en el turismo cultural, residencial de baja densidad y del sector agroalimentario de lujo. Su casco antiguo e inmediaciones rurales albergan históricos pazos barrocos y casonas señoriales rehabilitadas con presupuestos millonarios como propiedades de alquiler íntegro vacacional con servicio de mayordomía privada. El municipio ofrece un entorno de máxima tranquilidad, disponiendo de helipuertos civiles.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','lujo','Turismo de lujo','La capital del Pallars Sobirà funciona como el centro de operaciones para el turismo de alta montaña y deportes de aguas bravas en formato premium [Image 4]. Su infraestructura exclusiva evita las aglomeraciones y se enfoca en chalets de montaña de diseño rústico-vanguardista y hoteles boutique orientados al bienestar físico [Image 5]. El municipio cuenta con empresas de turismo activo que diseñan descensos de ríos privados con guías olímpicos en exclusiva para directivos de multinacionales. Ofrece helipuertos operativos para transfers directos a pistas de esquí cercanas y una gastronomía de alta montaña galardonada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03025','lujo','Turismo de lujo','Municipio residencial e interior costero consolidado como un búnker de alta seguridad para la élite de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','lujo','Turismo de lujo','Histórica villa renacentista que esconde un potente reducto de ultra-lujo y total opacidad en el corazón de la Sierra de Alcaraz. Carece de infraestructura urbana masiva, pero su elevada puntuación radica en albergar inmensas fincas de caza mayor y dehesas fortificadas de miles de hectáreas propiedad de grandes fortunas europeas. Estas propiedades de súper-lujo cuentan con helipuertos autorizados, seguridad perimetral avanzada con guardería propia, pabellones de caza de alto standing y servicios de chef privado que se desplazan exclusivamente para la recepción de inversores internacionales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','lujo','Turismo de lujo','Conocido internacionalmente como el balcón de la Serranía de Ronda, es el refugio predilecto de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','lujo','Turismo de lujo','El municipio más extenso de la isla alberga una de las infraestructuras de estilo de vida premium más completas y diversificadas. Su fachada marítima cuenta con urbanizaciones de acantilado hiper-exclusivas como Cala Blava y Son Verí Nou, compuestas por mansiones multimillonarias. Su infraestructura de súper-lujo está capitaneada por dos campos de golf de nivel internacional (Golf Maioris y Son Antem), hoteles de 5 estrellas Gran Lujo como el Cap Rocat (una antigua fortaleza militar blindada reconvertida en el hotel más exclusivo y privado del Mediterráneo) y sofisticados beach clubs de alta gama.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','lujo','Turismo de lujo','Nota de enfoque premium: Más allá de su tradicional puerto pesquero, el litoral de su término municipal que ladea la reserva de la biosfera de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','lujo','Turismo de lujo','Municipio costero y residencial de baja densidad preferido por las grandes fortunas de la cornisa norte que buscan máxima privacidad y descanso. Su infraestructura premium destaca por la espectacular península de Cuchía y la urbanización en torno al campo de Golf Abra del Pas, un recorrido situado en la misma desembocadura del río Pas. Cuenta con mansiones vanguardistas blindadas en entornos naturales protegidos, acceso inmediato a prestigiosos centros ecuestres y servicios de conserjería personalizados para directivos industriales de la región.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','lujo','Turismo de lujo','El corazón geográfico y de alojamiento premium de la comarca del Ribeiro. Su infraestructura exclusiva se cimienta en la reconversión de monumentos históricos en complejos hoteleros de alta gama, destacando el Eurostars Monumento Monasterio de San Clodio (un.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','lujo','Turismo de lujo','Uno de los grandes bastiones residenciales de la zona oeste madrilena. Su infraestructura premium destaca por la urbanización blindada El Bosque, un complejo cerrado con estrictos controles de accesos donde se erigen mansiones de diseño vanguardista y máxima privacidad. Alberga prestigiosos centros ecuestres de alta competición, el club de golf colindante y centros de salud privados de alta gama. Su tejido urbano ofrece una sólida infraestructura de seguridad y servicios premium enfocados a altos directivos de multinacionales y diplomáticos que exigen un anonimato absoluto.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','lujo','Turismo de lujo','Villa histórica galardonada con la Medalla de Oro al Mérito en las Bellas Artes que funciona como el epicentro del "lujo silencioso" y la desconexión total en el norte de Tenerife. Su infraestructura premium prescinde del formato de cadenas hoteleras masivas. Se basa en la reconversión de espectaculares palacetes señoriales del siglo XVI y XVII en hoteles boutique de 5 estrellas Gran Lujo, como el Hotel San Roque. Dispone de un puerto deportivo adaptado a embarcaciones recreativas medianas, helipuertos privados autorizados y una alta cocina atlántica de vanguardia que atrae a la élite intelectual internacional.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','lujo','Turismo de lujo','Conjunto Histórico-Artístico consolidado como uno de los nodos mundiales del enoturismo premium y la cultura vitivinícola de alta gama. Su infraestructura de ultralujo está capitaneada por el Museo Vivanco de la Cultura del Vino (considerado uno de los mejores del mundo) y sus bodegas de vanguardia. El municipio ofrece salas de catas privadas subterráneas e históricas preparadas para inversores y coleccionistas mundiales, helipuertos operativos en sus fincas rústicas y hoteles boutique de diseño de alta gama que garantizan la máxima confidencialidad a empresarios corporativos globales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','lujo','Turismo de lujo','Municipio industrial y residencial que funciona como un potente pulmón inmobiliario rural de la aristocracia andaluza. Su infraestructura premium se basa en la concentración de históricas haciendas de olivar y fincas ganaderas de miles de hectáreas fortificadas con avanzados sistemas de seguridad privada, propiedad de grandes terratenientes y empresarios globales. Estas fincas de súper-lujo cuentan con helipuertos civiles homologados, picaderos profesionales dedicados a la cría de caballos de pura raza española y pabellones residenciales con servicios de chef privado de alto nivel bajo demanda.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17160','lujo','Turismo de lujo','Histórica villa marinera que ha desarrollado un modelo de turismo residencial e inmobiliario de alto standing protegido de la masificación. Su infraestructura de súper-lujo se desmarca del centro urbano y se despliega en la urbanización privada y blindada de Punta Brava, donde se erigen mansiones multimillonarias de diseño contemporáneo encajadas directamente en acantilados sobre el Mediterráneo. Dispone de un puerto deportivo con amarres de gran calado para yates de alta eslora, clubes de campo privados y una gastronomía ampurdanesa refinada respaldada por una densa oferta culinaria de autor.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','lujo','Turismo de lujo','Municipio que concentra una sólida infraestructura de turismo residencial, náutico y de estilo de vida premium en el entorno del Mar Menor. Su fachada marítima alberga la marina de Santiago de la Ribera y el puerto deportivo, con amarres para yates de gran eslora y servicios de chárter náutico VIP. Su infraestructura de alta gama incluye resorts cerrados con campos de golf de nivel internacional diseñados por firmas de renombre, urbanizaciones de villas inteligentes de diseño minimalista con seguridad perimetral avanzada 24/7 y clínicas privadas de bienestar médico y estético.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07002','lujo','Turismo de lujo','Destino residencial de interior predilecto de fortunas internacionales, altos ejecutivos e intelectuales centroeuropeos que buscan el concepto de "lujo rural señorial" con máxima discreción. Su infraestructura premium destaca por una densa red de históricas fincas rústicas mallorquinas (posesions) y mansiones de piedra totalmente blindadas y rediseñadas por arquitectos de vanguardia global. El municipio cuenta con exclusivas bodegas boutique que ofrecen catas privadas subterráneas para grandes coleccionistas, agroturismos de 5 estrellas Gran Lujo ocultos entre la naturaleza de la isla y restaurantes gourmet de alta cocina mallorquina.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','lujo','Turismo de lujo','Histórica villa señorial vinculada históricamente a los grandes linajes de la nobleza gallega que ha desarrollado un sólido segmento residencial e inmobiliario de alto standing integrado en las Rías Altas. Su infraestructura de alta gama destaca por la reconversión de antiguas casonas de piedra y pazos fortificados en complejos boutique que garantizan el anonimato absoluto. El municipio dispone de un puerto natural protegido idóneo para el fondeo discreto de embarcaciones de recreo de eslora media-alta y ofrece una selecta red gastronómica especializada en pescados y mariscos de máxima pureza.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','lujo','Turismo de lujo','Municipio que funciona como un búnker de "lujo silencioso" en el interior de la provincia, muy cotizado por empresarios internacionales que buscan total anonimato. Su infraestructura exclusiva prescinde del formato de cadenas hoteleras masivas y se enfoca en fincas rústicas señoriales rehabilitadas con presupuestos millonarios de alquiler íntegro premium. Cuenta con bodegas boutique de producción limitada que organizan catas privadas subterráneas para inversores de alta gama. El municipio dispone de helipuertos privados autorizados en propiedades particulares y servicios personalizados de conserjería que conectan rápidamente con los puertos deportivos de la Costa Blanca.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17144','lujo','Turismo de lujo','Exclusivo municipio medieval de piedra que conforma uno de los secretos mejor guardados del Ampurdán interior, a escasos minutos de las playas de Begur. Su infraestructura premium destaca por una nula densidad de turismo de masas y un mercado inmobiliario copado por masías fortificadas medievales totalmente restauradas con avanzados sistemas de seguridad y total opacidad. La planta hotelera del municipio se limita a hoteles boutique de 5 estrellas de baja densidad arquitectónica, con helipuertos privados operativos, clubes hípicos de alto rendimiento y restaurantes culinarios de autor que atraen a la élite financiera y corporativa global de Barcelona.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41059','lujo','Turismo de lujo','El principal nodo residencial, comercial y de alta dirección de la comarca del Aljarafe. Su infraestructura de alta gama destaca por la urbanización privada y blindada Simón Verde, un búnker de alta seguridad perimetral con patrullas 24/7 donde se erigen mansiones de diseño vanguardista e inteligente de gran envergadura. El municipio se beneficia de su cercanía logística inmediata a la capital andaluza, centros de negocios VIP con helipuertos, exclusivas clínicas de medicina estética personalizada, prestigiosos colegios internacionales y una selecta red de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','lujo','Turismo de lujo','Histórica capital costera que ha desarrollado un sólido sector inmobiliario residencial y de alojamiento de alto standing integrado en la naturaleza atlántica. Su infraestructura premium destaca por la marina del Puerto de Santa Cruz de la Palma, adaptada con amarres de gran calado para el mantenimiento y estancia discreta de yates de gran eslora y chárters VIP. El municipio prescinde del gigantismo hotelero y se enfoca en palacetes de arquitectura colonial canaria y antiguas haciendas rehabilitadas que garantizan el anonimato absoluto, complementado con experiencias exclusivas de astroturismo privado VIP con astrónomos personales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47116','lujo','Turismo de lujo','Uno de los grandes epicentros mundiales del enoturismo de ultra-lujo, internacionalmente codiciado por grandes coleccionistas e inversores del sector vinícola. Su infraestructura exclusiva se cimienta en bodegas legendarias de renombre global (como Alejandro Fernández Tinto Pesquera o Emilio Moro) que cuentan con proyectos arquitectónicos vanguardistas e históricos, helipuertos operativos en sus fincas para el traslado directo de clientes VIP mundiales, y comedores estrictamente privados para.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','lujo','Turismo de lujo','Destino histórico del veraneo aristocrático y el invierno VIP, famoso por su emblemático e histórico complejo termal. Su infraestructura premium destaca por el Balneario de Panticosa, un oasis de bienestar médico y de salud de alta gama situado a más de 1.600 metros de altitud, dotado de hoteles de 4 y 5 estrellas e instalaciones de spa de nivel internacional. El municipio ofrece urbanizaciones residenciales de chalets de piedra y madera noble con máxima seguridad privada, accesos rápidos a pistas de esquí con remontes exclusivos y una alta restauración gastronómica pirenaica.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','lujo','Turismo de lujo','Pintoresca villa marinera que ha desarrollado un modelo residencial e inmobiliario de alto standing y baja densidad en sus colinas y acantilados adyacentes. Su infraestructura premium huye de la sobreexposición urbana y se concentra en la reconversión de antiguas casonas de indianos y palacetes en hoteles boutique de alta gama que garantizan un anonimato total. Dispone en su entorno de espectaculares villas inteligentes integradas en parajes naturales protegidos, servicios de chárter VIP de.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','lujo','Turismo de lujo','Histórico puerto pesquero y estratégico que ha desarrollado un sólido sector residencial y turístico de alto standing enfocado a la náutica y la gastronomía sibarita. Su infraestructura premium destaca por su puerto deportivo, equipado con amarres para embarcaciones recreativas de media y gran eslora, chárters VIP y servicios de mantenimiento naval. El municipio alberga exclusivas urbanizaciones de chalets contemporáneos inteligentes cerca de parajes protegidos, casonas montañesas fortificadas y una alta restauración marina especializada en el procesado artesanal de conservas premium cotizadas a nivel mundial.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43137','lujo','Turismo de lujo','Municipio de interior que funciona como un búnker de "lujo silencioso" y desconexión absoluta para empresarios e inversores de la provincia de Barcelona. Su infraestructura premium prescinde de los desarrollos hoteleros masivos y se concentra en la adquisición y restauración millonaria de masías fortificadas históricas rodeadas de viñedos. El municipio cuenta con bodegas boutique de producción ultra-limitada amparadas bajo la D.O. Penedès, las cuales ofrecen salas de catas subterráneas privadas, helipuertos civiles autorizados en propiedades particulares y servicios de chef a domicilio de alta gama.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','lujo','Turismo de lujo','Pequeño municipio jiennense cuya infraestructura de súper-lujo gira en torno a su imponente Castillo de Canena (siglo XVI), un baluarte de propiedad privada que da nombre a una de las marcas de aceite de oliva virgen extra más exclusivas del mundo. El término municipal alberga majestuosas haciendas andaluzas de olivar centenario transformadas en complejos boutique de baja densidad que garantizan una total opacidad. Ofrece visitas privadas y catas dirigidas en almazaras de diseño arquitectónico vanguardista para inversores y personalidades internacionales de alto poder adquisitivo, complementado con zonas de helipuerto autorizadas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','lujo','Turismo de lujo','Municipio ubicado en la cumbre de Gran Canaria, catalogado como uno de los pueblos más bellos de España, que funciona como un cotizado nodo de turismo de bienestar y desconexión premium. Su infraestructura exclusiva destaca por el Parador de Cruz de Tejeda, un hotel de alta gama con un spa hidrotermal colgado sobre un acantilado volcánico con vistas panorámicas al Roque Nublo. El municipio ofrece un entorno de máxima seguridad geográfica, chalets de montaña de diseño rústico-vanguardista de alquiler íntegro exclusivo y una gastronomía de vanguardia basada en la almendra y los productos locales elevados a la alta cocina de autor.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','lujo','Turismo de lujo','Histórica villa marinera que ha desarrollado un modelo de turismo residencial e inmobiliario de alto standing integrado en el Geoparque de la Costa Vasca. Su infraestructura premium destaca por su puerto deportivo protegido, apto para el amarre discreto de embarcaciones recreativas y veleros de alta eslora, y por exclusivas urbanizaciones de chalets contemporáneos inteligentes construidos sobre acantilados marinos con patrullas de vigilancia privada. Su oferta gastronómica se ha sofisticado con asadores de pescado de primer nivel mundial que surten a un perfil corporativo internacional que exige confidencialidad absoluta.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45200','lujo','Turismo de lujo','El gran búnker rústico de los Montes de Toledo, consolidado internacionalmente como uno de los destinos más exclusivos para el turismo cinegético y de fincas de ultra-lujo. Carece por completo de infraestructura urbana masiva, pero su elevada puntuación radica en albergar masivas fincas fortificadas de miles de hectáreas propiedad de la aristocracia europea y magnates mundiales de las finanzas. Estas propiedades de súper-lujo cuentan con helipuertos civiles homologados, pabellones de caza de alto standing con sistemas de seguridad militarizada, guardería privada propia permanente y servicios de chefs con Estrella Michelin que se desplazan en exclusiva para eventos restringidos.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','lujo','Turismo de lujo','El oasis del bienestar, la hidroterapia premium y el enoturismo de alta gama en el corazón de la comarca del Ribeiro. Su pilar fundamental de infraestructura premium es el Hotel Balneario Laias Caldaria, un espectacular complejo hotelero y termal de alta gama situado a orillas del río Miño, muy utilizado por deportistas de élite y selecciones internacionales. El municipio destaca por sus villas de diseño contemporáneo integradas en la naturaleza gallega, pazos históricos de gestión privada destinados al alquiler vacacional íntegro y exclusivas bodegas boutique que organizan catas privadas subterráneas para grandes coleccionistas de vino mundiales.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','lujo','Turismo de lujo','Histórica villa marinera y nobiliare de la cornisa norte que ha consolidado un potente segmento residencial, náutico y gastronómico de alto standing dentro del Parque Natural de Oyambre. Su infraestructura premium destaca por su puerto deportivo perfectamente equipado para el amarre de yates recreativos y veleros de alta eslora, y por búnkeres inmobiliarios de baja densidad compuestos por casonas montañesas fortificadas y chalets vanguardistas inteligentes en primera línea de costa. Su gastronomía marina es de primer nivel mundial, especializada en el marisco salvaje de lonja, atrayendo a directivos y empresarios que exigen la máxima privacidad.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','lujo','Turismo de lujo','Uno de los municipios residenciales más exclusivos y con mayor renta per cápita de Cataluña, pegado a la zona alta de Barcelona capital. Su infraestructura de ultra-lujo destaca por urbanizaciones ultravigiladas como La Mallola o Bellsoleig, repletas de mansiones vanguardistas e inteligentes de diseño de autor elegidas por directivos de multinacionales y futbolistas de élite. El municipio cuenta con prestigiosos colegios internacionales (como el American School of Barcelona), clínicas privadas de medicina estética, y un urbanismo de baja densidad protegido por patrullas de seguridad 24/7 que garantiza el anonimato total y la paz de sus residentes premium.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','lujo','Turismo de lujo','Conocida históricamente como la "Sevilla Chica", esta villa señorial funciona como el nodo logístico y de servicios premium para los grandes terratenientes y empresarios agroganaderos del sur de Extremadura. Su planta hotelera destaca por el Parador de Zafra, ubicado en el imponente Palacio de los Duques de Feria (siglo XV) con suites de alto standing decoradas con artesonados históricos. El entorno rústico del municipio alberga dehesas fortificadas de miles de hectáreas dedicadas a la cría en pureza de ganado ibérico de bellota y caballos de pura raza española.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','lujo','Turismo de lujo','Escondido en el corazón del Parque Natural de la Sierra de Aracena y Picos de Aroche, este pintoresco municipio funciona como un oasis de "lujo silencioso" y total desconexión para altos ejecutivos. Su infraestructura premium prescinde del formato de grandes complejos comerciales y se enfoca en la rehabilitación multimillonaria de cortijos serranos y fincas de castaños centenarios reconvertidos en alojamientos boutique de ultra-.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20061','lujo','Turismo de lujo','Histórica villa costera y marinera que funciona como un cotizado reducto residencial para las grandes fortunas de San Sebastián. Su infraestructura premium destaca por el puerto deportivo ubicado en la desembocadura del río Oria, idóneo para el amarre discreto de embarcaciones.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47038','lujo','Turismo de lujo','Pequeño municipio que esconde uno de los proyectos vinícolas y paisajísticos de ultra-lujo más exclusivos de la Ribera del Duero. Su infraestructura de alta gama se cimienta en bodegas boutique de producción ultralimitada dedicadas a la elaboración de vinos de alta costura para grandes coleccionistas mundiales. Estas propiedades cuentan con espectaculares salas de catas privadas y zonas de aterrizaje autorizadas para helicópteros destinadas a inversores VIP internacionales. Ofrece alojamientos rurales premium de baja densidad y una total desconexión en un entorno geográfico blindado contra la masificación.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07058','lujo','Turismo de lujo','Ubicado en las faldas de la Sierra de Tramuntana, este municipio se ha posicionado en el segmento del "lujo lento" y el anonimato absoluto para el mercado premium centroeuropeo. Su infraestructura exclusiva prescinde del gigantismo turístico y se concentra en fincas.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','lujo','Turismo de lujo','Galardonado repetidamente por la conservación de su arquitectura morisca, este pueblo blanco de montaña se ha consolidado como un destino de "lujo descalzo" sumamente cotizado por fortunas y artistas internacionales. Su infraestructura premium se integra invisiblemente en la naturaleza y destaca por promociones de villas residenciales inteligentes con piscinas infinitas situadas en las colinas que miran hacia el mar de Alborán. El municipio garantiza un anonimato total, ofreciendo servicios de helipuerto privado bajo demanda, galerías de arte privadas, talleres artesanales exclusivos y una gastronomía km 0 hiperrefinada.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','lujo','Turismo de lujo','El gran bastión del turismo residencial de alta gama enfocado en el sector ecuestre internacional de élite en la periferia norte de la capital. Su infraestructura estrella destaca por la Hípica San Agustín y las grandes dehesas privadas colindantes, equipadas con instalaciones olímpicas de última generación, picaderos cubiertos y pistas de salto utilizadas por jinetes de nivel internacional. Su planta inmobiliaria premium consta de fincas y mansiones inteligentes blindadas ocultas en la naturaleza madrileña que garantizan el anonimato absoluto a empresarios y deportistas, respaldadas por áreas de helitransporte autorizadas y una selecta restauración gourmet de caza y alta cocina castellana.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17081','lujo','Turismo de lujo','Nodo estratégico de la Costa Brava interior que funciona como un cotizado reducto para el "lujo silencioso" y los deportes de precisión. Su infraestructura deportiva premium destaca por albergar el Empordà Golf Club, un resort de alto standing dotado de dos recorridos de campeonato de 18 hoyos (Links y Forest) diseñados por el célebre arquitecto Robert von Hagge. El complejo inmobiliario se integra en la naturaleza mediante exclusivas masías medievales restauradas con presupuestos millonarios y sistemas avanzados de seguridad. Ofrece agroturismos de 5 estrellas de baja densidad arquitectónica, helipuertos operativos en las fincas y una alta restauración gastronómica ampurdanesa.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','lujo','Turismo de lujo','El portal de entrada a los Pirineos que ha desarrollado un sólido nicho de turismo premium deportivo enfocado al golf de alta montaña. Su gran pilar de infraestructura exclusiva es el Margas Golf, un campo de 18 hoyos diseñado personalmente por el campeón español José María Olazábal, caracterizado por sus lagos artificiales y un diseño técnico de nivel profesional adaptado a la orografía pirenaica. El municipio ofrece urbanizaciones residenciales de chalets de piedra y madera noble con estricta seguridad privada, hoteles boutique enfocados al bienestar de montaña y servicios de transfers VIP directos a las estaciones de esquí del Valle de Tena.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90009','lujo','Turismo de lujo','Uno de los grandes epicentros mundiales del turismo de salud y la medicina preventiva de ultra-lujo. Su gran pilar de infraestructura internacional es el icónico SHA Wellness Clinic, un resort médico galardonado globalmente que atrae a jefes de Estado, jeques y grandes empresarios mundiales. Este búnker de alta seguridad y diseño minimalista ofrece tratamientos de longevidad celular, medicina genómica, planes de nutrición macrobiótica y terapias antienvejecimiento con tecnología médica de vanguardia. Dispone de helipuertos civiles autorizados, suites privadas fortificadas con piscinas infinitas suspendidas que miran a la bahía de Altea y un entorno de privacidad absoluta blindado contra la exposición mediática.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47127','lujo','Turismo de lujo','Uno de los grandes nodos mundiales del enoturismo de súper-lujo y la discreción absoluta en la "Milla de Oro" de la Ribera del Duero. Su infraestructura exclusiva destaca por albergar bodegas de prestigio mundial que cuentan con sus propios helipuertos homologados y pistas de aterrizaje privadas autorizadas para aeronaves ligeras dentro de sus propiedades amuralladas. Estas instalaciones reciben de forma regular a grandes coleccionistas e inversores internacionales del sector vitivinícola mediante transfers directos en jets corporativos. Cuenta con suites de alta gama integradas en fincas históricas, santuarios de barricas inaccesibles para el gran público y comedores estrictamente privados con chefs de nivel Michelin.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','lujo','Turismo de lujo','Uno de los municipios litorales más exclusivos de la periferia de Barcelona, caracterizado por sus búnkeres inmobiliarios frente al Mediterráneo. Su infraestructura premium destaca por urbanizaciones cerradas de baja densidad con impresionantes sistemas de seguridad inteligente, cámaras térmicas y patrullas de vigilancia las 24 horas que blindan las residencias de deportistas de élite y.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','lujo','Turismo de lujo','El gran baluarte rústico del interior andaluz, consolidado internacionalmente como uno de los destinos más codiciados para el turismo cinegético y de fincas de ultra-lujo. Carece por completo de infraestructura urbana masiva, pero su elevada puntuación radica en albergar inmensas dehesas de encinas milenarias y fincas fortificadas de miles de hectáreas en pleno Parque Natural, propiedad de terratenientes históricos, magnates mundiales de las finanzas y miembros de familias reales europeas. Estas propiedades privadas de súper-lujo cuentan con helipuertos civiles homologados, pabellones de caza de alta gama con sistemas de seguridad militarizada y servicios de chef privado que se desplazan exclusivamente para la temporada de monterías mayores.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90890','lujo','Turismo de lujo','Pequeño municipio de piedra del interior ampurdanés consolidado como el refugio predilecto de la alta burguesía catalana e inversores centroeuropeos que exigen anonimato total. Su infraestructura premium prescinde del formato hotelero tradicional y se basa en la adquisición de masías medievales fortificadas y palacetes rurales restaurados con presupuestos millonarios. El municipio destaca por sus selectas tiendas de antigüedades, galerías de arte privadas y talleres de restauración artística de alta gama que surten a los decoradores más cotizados del continente. Cuenta con helipuertos privados operativos en fincas particulares, patrullas de seguridad perimetral y un entorno geográfico blindado contra la masificación.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41065','lujo','Turismo de lujo','Municipio estratégico de la campiña andaluza que funciona como un destino de ultra-lujo discreto especializado en el sector hípico señorial, la hípica de alta competición y el turismo residencial de interior. Su infraestructura de alta gama destaca por albergar imponentes haciendas de olivar y fincas de miles de hectáreas fortificadas con avanzados sistemas de seguridad privada, propiedad de terratenientes y empresarios del sector agroalimentario global. Estas propiedades de súper-lujo cuentan con helipuertos civiles homologados, picaderos olímpicos cubiertos dedicados en exclusiva a la cría y exportación de caballos de pura raza española y pabellones de uso estrictamente privado con servicios de chef de alto nivel bajo demanda.','inventario_lujo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35029','lujo','Turismo de lujo','Ubicado en el linde del Parque Nacional de Timanfaya, este municipio costero e interior se ha posicionado en el segmento del "lujo descalzo" y la desconexión ecológica de alto standing. Su infraestructura exclusiva huye del turismo masivo y se concentra en villas eco-vanguardistas de baja densidad y antiguas casonas de piedra volcánica rehabilitadas con un diseño integrado en la naturaleza, inspiradas en el legado de César Manrique. El municipio ofrece un entorno de máxima seguridad geográfica, helipuertos privados autorizados en propiedades particulares para transfers rápidos y un acceso privilegiado a los fondeaderos naturales del litoral, idóneos para el descanso y avituallamiento discreto de yates privados.','inventario_lujo_pdf');
